window.__HOT_STORIES__ = {"schemaVersion":1,"updatedAt":"2026-11-14T18:14:55.892Z","stories":{"d01448e7-e6ef-4224-9e13-5f4b350dd6ed":{"publicId":"d01448e7-e6ef-4224-9e13-5f4b350dd6ed","title":"黄仁勋辞任英伟达CEO并退出董事会","status":"active","sourceCount":24,"reportCount":70,"firstReportAt":"2026-10-29T13:42:38.000Z","latestAt":"2026-11-14T14:49:22.000Z","latest":"X.PIN 转发 WSJ 关于黄仁勋辞任 Nvidia 的社论并附新加坡政府澄清声明","digest":"英伟达董事会11月12日宣布，联合创始人、总裁兼CEO黄仁勋辞去总裁、CEO及董事职务，即刻生效，结束33年执掌。此前他承认与Megaspeed前高管Alice Huang的婚外情，美国情报界认为后者为中国国家安全部招募的间谍；《纽约时报》又曝出他与一名直接下属的第二段婚外情。董事会任命CFO Colette Kress为临时CEO，并启动内外部继任者遴选，前Synopsys CEO Harvey Jones出任公司首任董事长。\n\n董事会此前于周末启动独立调查，并称无理由认为国家安全或公司机密受损；《华尔街日报》随后报道董事会接近决定是否罢免黄仁勋。消息公布后，英伟达股价一度下跌13%至14%，市值回落至4万亿美元以下。\n\n事件还牵出芯片出口争议：The Information报道称Alice Huang相关网络向中国买家转手约75亿美元英伟达硬件；众议院中国特设委员会主席Moolenaar要求英伟达任命把国家安全置于首位的领导层，并推动年底国防授权法案通过出口管制立法。","digestUpdatedAt":"2026-11-14T15:18:10.457Z","reports":[{"id":"ni18shok3lh70l1e49nazmgdc","title":"黄仁勋离开 Nvidia 后，亚洲各国政府如何回应","summary":"黄仁勋离开 Nvidia 后，亚洲多国政府相继回应：韩国科技部称 Nvidia 重申将向韩国供应 260,000 块先进 GPU 并继续联合 AI 项目，台湾经济部长龚明鑫认为此事不太可能显著改变全球 AI 产业增长，日本产业省表示将密切关注 Nvidia。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-14T16:34:15.000Z","url":"https://techcrunch.com/2026/11/14/asian-governments-react-to-nvidia-ceo-jensen-huangs-exit/"},{"id":"wum2o1ou49rhookuv10ck6ow6","title":"X.PIN 转发 WSJ 关于黄仁勋辞任 Nvidia 的社论并附新加坡政府澄清声明","summary":"X.PIN 引用 WSJ 社论，称黄仁勋辞任 Nvidia 虽有必要但对公司和美国 AI 产业造成遗憾损害，并猜测这或许是中国的计划。所附图片为新加坡政府 2026 年 10 月 31 日的澄清声明，针对 WSJ 10 月 30 日关于 Alice Huang 涉嫌向中国传递信息、与黄仁勋关系密切的报道，声明新加坡政府及其官员从未表达相关担忧，也从未就 Alice Huang 展开此类调查，并附上了与 WSJ 的往来问答。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-14T14:49:22.000Z","url":"https://x.com/thexpin/status/2121616487249219804"},{"id":"p1mfh9oe0xbq4evyru5pp1ikt","title":"Nvidia 危机与 Anthropic IPO 前夜的 Cerebral Valley AI Summit 现场观察","summary":"Newcomer 在旧金山 Cerebral Valley AI Summit 现场报道：Jensen Huang 因第二段婚外情披露辞职，Reuters 当天报道存在第三段，与会者多认为 Nvidia 短期无碍但生态承压，Databricks CEO 称其对整个生态是打击。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-13T19:27:39.000Z","url":"https://www.newcomer.co/p/nvidia-crises-anthropic-ipo-and-off"},{"id":"cs8aaqi9s05ph4pos2vguvohq","title":"Ed Zitron 长文解析 NVIDIA 走私指控与其历史争议","summary":"Ed Zitron 在付费长文中分析围绕 NVIDIA 的 GPU 走私指控网络，并引用 Culper Research 2026 年 5 月报告称相关出货可能占其 2026 财年营收超 20%（逾 430 亿美元）。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:19:39.000Z","url":"https://www.wheresyoured.at/hg-megaspeed/"},{"id":"il5gmcwg4dn1n3sj5vl2bsuij","title":"黄仁勋丑闻时间线：婚外情、疑似中国间谍与辞任英伟达 CEO","summary":"英伟达联合创始人黄仁勋在承认婚外情后辞去 CEO 一职，CFO Colette Kress 出任临时 CEO。美方怀疑其情人之一、Megaspeed 高管 Alice Huang 为中国间谍，该公司两年内采购了价值 48 亿美元的英伟达芯片。路透社与《纽约时报》还报道了另外两段婚外情，美国国会已就芯片对华销售展开调查并要求黄仁勋作证。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T15:58:00.000Z","url":"https://techcrunch.com/2026/11/13/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"wkxqhc700pv5zgpew0cj5zyec","title":"Vergecast 播客解读黄仁勋辞任 NVIDIA CEO 后的连锁影响","summary":"The Vergecast 播客中 David Pierce 与 Nilay 梳理 NVIDIA CEO 黄仁勋周四辞职事件，并讨论后续可能展开的更大故事：NVIDIA 在中国的业务、美国政府的态度，以及整个 AI 行业的稳定性。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T14:47:16.000Z","url":"https://www.theverge.com/podcast/1032866/jensen-huang-nvidia-china-trump-vergecast"},{"id":"se0y4v3gihr6s0jmrc5vuv1zo","title":"AINews：黄仁勋辞任 NVIDIA CEO，Colette Kress 出任临时 CEO","summary":"Latent Space 的 AI 新闻日报头条是 NVIDIA 宣布黄仁勋在任职 33 年后辞去 CEO、总裁和董事职务，CFO Colette Kress 出任临时 CEO，SEC 文件显示董事会于 11 月 11 日接受辞呈，此前董事会已就 NYT 报道的绯闻事件展开独立调查。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-13T09:04:13.000Z","url":"https://latent.space/p/ainews-jensen-huang-resigns-after-33-years-leading-nvidia/"},{"id":"c38th8p4klxei4v40fxntey09","title":"黄仁勋辞任英伟达 CEO 全时间线复盘：两桩风波、接班人与 33 年生涯","summary":"11 月 12 日英伟达公告黄仁勋辞去总裁、CEO 和董事职务，即刻生效，未提原因；股价当日跌 13%，市值回落至 4 万亿美元以下，CFO 科莱特·克雷斯临时接任，哈维·琼斯成为公司 33 年来首位董事长。","sourceName":"X：卡尔的 AI 沃茨 (@aiwarts)","firstParty":false,"publishedAt":"2026-11-13T04:17:46.000Z","url":"https://x.com/aiwarts/status/2121095150114140317"},{"id":"sntaq2q8jo5gkp6hpgn0wy7g6","title":"Rohan Paul 日报：黄仁勋结束 33 年任期辞任 Nvidia CEO，Colette Kress 任临时 CEO","summary":"Rohan Paul 发布日报称，黄仁勋辞任 Nvidia CEO，结束 33 年任期，CFO Colette Kress 出任临时 CEO。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T02:05:59.000Z","url":"https://x.com/rohanpaul_ai/status/2121061984896708744"},{"id":"yb6o3s9lyxkb8xf7ykhrj3cr1","title":"黄仁勋辞任 Nvidia CEO，Casey Newton 撰文评析硅谷创始人崇拜的终结","summary":"Nvidia 于周四宣布 CEO 黄仁勋辞职，CFO Colette Kress 暂代 CEO，此前纽约时报曝光其第二段婚外情，路透社随后披露第三段。作者 Casey Newton 评析其职业生涯，指出硅谷创始人崇拜带来的两大问题，包括富豪寡头化和 key-man 风险，并称黄仁勋没有继任计划。","sourceName":"Platformer（热点 RSS）","firstParty":false,"publishedAt":"2026-11-13T01:43:23.000Z","url":"https://www.platformer.news/jensen-huang-resigns-founder-cult-accountability/"},{"id":"y51nb19h2bj96to0swwkv57oy","title":"黄仁勋辞任英伟达CEO：作者梳理14天时间线与33年生涯","summary":"11月12日英伟达公告黄仁勋辞去总裁、CEO和董事职务，股价当日跌13%，市值跌回4万亿美元以下，CFO科莱特·克雷斯临时接任。","sourceName":"公众号：卡尔的AI沃茨","firstParty":false,"publishedAt":"2026-11-13T01:03:00.000Z","url":"https://mp.weixin.qq.com/s/RB5f6wfZgI46D8ux_vK5LA"},{"id":"uef3cjv8f2j9x82ncz5frcfjg","title":"黄仁勋辞去英伟达总裁与CEO职务，卡兹克梳理事件始末","summary":"作者梳理黄仁勋辞去英伟达总裁、首席执行官和董事职务的来龙去脉，从2022年美国对A100、H100等芯片禁售写起，串起Megaspeed、黄乐与黄仁勋的关联、75亿美元芯片交易指控、《纽约时报》与The Information的系列调查报道，到11月12日晚公告辞职的14天时间线，并附带股价开盘下跌14个点等反应。","sourceName":"X：卡兹克 (@Khazix0918)","firstParty":false,"publishedAt":"2026-11-13T00:29:40.000Z","url":"https://x.com/Khazix0918/status/2121037747259625601"},{"id":"hqidckwtzcu63rwc19czidjld","title":"黄仁勋辞去英伟达 CEO，Hugging Face CEO 德朗格表态继续力挺开源 AI","summary":"黄仁勋于 11 月 12 日辞去英伟达总裁、CEO 及董事职务，即刻生效，CFO 科莱特·克雷斯出任临时 CEO，公司启动新 CEO 遴选。Hugging Face CEO 德朗格在领英称这是令人难过的一天，表示将比以往更努力捍卫开源人工智能。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T23:56:58.007Z","url":"https://www.ithome.com/1/026/469.htm"},{"id":"t86m3q7vdlqmvm2zmx91vps5a","title":"黄仁勋辞去英伟达总裁兼CEO，作者梳理14天风波始末","summary":"英伟达公告黄仁勋辞去总裁、CEO和董事职务，即刻生效，股价开盘下跌14个点。作者依据《纽约时报》、The Information 等报道梳理脉络：从2022年A100、H100对华禁售，到 Megaspeed 采购争议、黄乐被情报机构认定涉间谍活动，再到婚外情曝光后董事会于10月29日起14天内收网，黄仁勋在英伟达33年的时代就此结束。","sourceName":"公众号：数字生命卡兹克","firstParty":false,"publishedAt":"2026-11-12T23:56:00.000Z","url":"https://mp.weixin.qq.com/s/ToplAo9NHP356Fu-hbYlsg"},{"id":"ey8wwzav6ohoxh11jw491kcjg","title":"黄仁勋辞职引发对 Nvidia 开源 AI 战略延续性的疑问","summary":"Nvidia CEO 黄仁勋周四因承认与一名涉嫌中国间谍者的婚外情而辞职，引发对其开源 AI 支持路线能否延续的疑问。他此前推动 Nemotron 开源模型、支持收购 Hugging Face 的 130 亿美元交易，并牵头的 25 家公司联名信反对政府过度限制开源权重模型；CFO Colette Kress 已出任临时 CEO。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:39:23.000Z","url":"https://techcrunch.com/2026/11/12/jensen-huangs-exit-puts-nvidias-support-for-open-source-in-question/"},{"id":"n73ab4h9gqlu6ucv69ynzxln4","title":"SemiAnalysis 分析黄仁勋辞任 Nvidia 后的公司结构与出口管制走向","summary":"SemiAnalysis 长文分析黄仁勋辞任 Nvidia CEO 后的连锁影响，作者推测其去职与 GPU 走私及美国推动 RASA 出口管制立法有关。文中指出公司约 60 名直管高管的扁平结构依赖黄本人，继任者 Colette Kress 为临时 CEO，Ian Buck 与 Jonah Alben 被视为技术侧人选但无人能全面接替。","sourceName":"SemiAnalysis 长文 RSS（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:06:26.000Z","url":"https://newsletter.semianalysis.com/p/nvidia-and-the-world-without-jensen"},{"id":"licdk6vosezxouovor3gvtcpe","title":"The Verge 分析黄仁勋辞职与 Nvidia 芯片走私疑云","summary":"The Verge 作者 Elizabeth Lopatto 分析 Nvidia 宣布黄仁勋辞职一事，认为第二桩婚外情只是导火索，真正原因或与芯片走私指控有关。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T17:44:33.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032069/jensen-huang-resignation-affair-chips-smuggling"},{"id":"rda6uss1k4k96ygzfl7a3byk0","title":"美众议院中国特设委员会主席 Moolenaar 就黄仁勋辞任 NVIDIA 发表声明","summary":"美众议院中国特设委员会主席 Rep. John Moolenaar 就黄仁勋辞任 NVIDIA 发表声明，称其被解职是一个本可避免的不幸结局。他表示 NVIDIA 现在必须改变公司治理方式，任命把国家安全置于最优先的领导层，并称国会应尽快在年底国防授权法案中通过两党出口管制立法。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T17:27:52.000Z","url":"https://x.com/rohanpaul_ai/status/2120931596396335208"},{"id":"sowwn4rv7ggtd41l0d469f1id","title":"Jensen Huang 被 Nvidia 董事会罢免 CEO 后，可能冲击 AI 行业的五个方面","summary":"Nvidia 董事会于周四罢免 CEO Jensen Huang，起因是他承认婚外情，且其中一名对象被美国政府怀疑为中国间谍、并任职于涉嫌走私 Nvidia 芯片的新加坡 neocloud。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:32:33.000Z","url":"https://techcrunch.com/2026/11/12/five-ways-jensen-huangs-ouster-from-nvidia-could-damage-the-ai-industry/"},{"id":"o8bau0c6koaa9ibvrxjfpl32e","title":"黄仁勋辞任英伟达CEO：中国究竟想从他身上得到什么？","summary":"黄仁勋辞去英伟达CEO职务，此前其与一名被指为中国间谍的女性存在关联的传闻持续发酵。布鲁金斯学会中国中心研究员Kyle Chan在Decoder访谈中分析，中国接近黄仁勋的重点可能不在GPU设计细节，而在于他对特朗普的直接影响力和美国政策制定过程的信息。访谈还讨论了DeepSeek R1、CUDA生态及华为等国产AI芯片替代路径。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:30:00.000Z","url":"https://www.theverge.com/podcast/1031260/nvidia-jensen-huang-resign-china-spy-scandal-ai-chips-trump"},{"id":"toq4wymx9maq8lhhz8jryi0sv","title":"黄仁勋辞职后，Nvidia 与 AI 热潮的未来走向分析","summary":"Azeem Azhar 分析黄仁勋辞任 Nvidia CEO 后的影响，CFO Colette Kress 将临时接任。他指出 Nvidia 五年间售出近 1400 万颗旗舰 AI 芯片、占市场 85%，并向 neocloud 提供财务担保、过去一年在欧洲投资近 100 亿美元；与乔布斯离任时不同，公司没有准备好的继任者，而黄仁勋本人一直是 AI 生态的关键纽带。","sourceName":"Azeem Azhar：Exponential View（RSS）","firstParty":false,"publishedAt":"2026-11-12T16:19:28.000Z","url":"https://www.exponentialview.co/p/jensen-huang-and-the-future-of-the"},{"id":"jferw1o1blgp1kv5z4no8qb5s","title":"NVIDIA CEO 黄仁勋辞职，CFO Colette Kress 出任临时 CEO","summary":"NVIDIA 联合创始人黄仁勋于当天早晨辞去 CEO 和董事职务，此前董事会对其与直属下属的多段婚外情及一名涉嫌中国间谍的调查展开调查。董事会任命任职超过 13 年的 CFO Colette Kress 为临时 CEO，Harvey Jones 出任首任董事会主席并致信员工；Kress 在首封临时 CEO 信中称这是一段极其艰难的时期，公司将于 11 月 18 日 9am PT 举行全员会议。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T15:48:12.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032028/read-nvidias-internal-emails-jensen-huang"},{"id":"l7dv9twcz25784wh4ttbhxm78","title":"Nvidia CEO 黄仁勋辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia 董事会宣布，执掌公司 33 年的联合创始人兼 CEO 黄仁勋辞去总裁、CEO 及董事职务，即刻生效。辞职发生在媒体报道他与一名涉嫌中国间谍及其一位直接下属有婚外情之后，公司此前从未设立继任计划。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T15:37:29.000Z","url":"https://techcrunch.com/2026/11/12/jensen-huang-is-out-at-nvidia-who-is-colette-kress-his-interim-replacement/"},{"id":"xe5jgbho8qhh6ahx1353wdycv","title":"NVIDIA 官宣 CEO 过渡，发布声明链接","summary":"NVIDIA Newsroom 宣布 CEO 过渡，附官方新闻稿链接 https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition。转发者 X.PIN 仅以“Such an era!”感叹，未补充细节。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-12T14:59:46.000Z","url":"https://x.com/thexpin/status/2120894325370577402"},{"id":"aol3stj5rjrl9sq35s3d4fzt6","title":"《大西洋月刊》谈黄仁勋在华盛顿的影响力","summary":"《大西洋月刊》有篇有意思的文章。\n\n这期节目展示了黄仁勋的影响力在华盛顿扩散得有多广。\n\n据文章称，在报道公开前数月，警告就已传达至政府高层官员。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T14:53:11.000Z","url":"https://x.com/rohanpaul_ai/status/2120892671178973263"},{"id":"cq52ebt0mx19monojyqyuxdo1","title":"黄仁勋辞任 Nvidia CEO，CFO Colette Kress 接任临时负责人","summary":"Gary Marcus 称黄仁勋已辞去 Nvidia CEO 职务，董事会推动其离任，由 CFO Colette Kress 出任临时负责人。他表示消息公布后 Nvidia 股价跌幅从盘前 8% 扩大到开盘时的 13%，并担心黄仁勋主导的循环融资可能崩塌，以及此前承诺投入 Anthropic 的数十亿美元 IPO 资金是否兑现成为焦点。他同时列举了国会调查、中国市场影响和政治层面的后续不确定性。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:44:04.000Z","url":"https://garymarcus.substack.com/p/jensen-huang-resigns"},{"id":"m76r4bnrvb21vkm8wn2khk0jr","title":"Kate Clark 转发 WSJ 报道称 Nvidia 正准备罢免 CEO 黄仁勋并征集信源","summary":"记者 Kate Clark 分享 WSJ 报道链接，该报道称 Nvidia 正准备罢免 CEO 黄仁勋。她同时留下 Signal 联系方式 415-409-9095，征集关于此事对私募市场、交易撮合、融资及 AI 行业连锁影响的爆料与讨论。","sourceName":"X：Kate Clark (@KateClarkTweets)","firstParty":false,"publishedAt":"2026-11-12T14:39:04.000Z","url":"https://x.com/KateClarkTweets/status/2120889116250288597"},{"id":"xraa42gmh7ndg2a3wvenh2rnv","title":"黄仁勋丑闻时间线：承认婚外情、辞去英伟达 CEO","summary":"英伟达联合创始人黄仁勋承认婚外情后，于 11 月 12 日辞去 CEO 一职，CFO Colette Kress 出任临时 CEO。此前有报道称其婚外情对象 Alice Huang 被美方怀疑为中国间谍，另一段与英伟达副总裁 Kimberly Powell 的婚外情也被《纽约时报》曝出。英伟达董事会已启动独立调查，美国国会还计划传唤黄仁勋作证。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:30:01.000Z","url":"https://techcrunch.com/2026/11/12/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"hfrol86d5xxs0jzhviul1dlof","title":"黄仁勋辞任 Nvidia CEO 并退出董事会，任职超 33 年","summary":"黄仁勋辞去 Nvidia CEO 并退出董事会，结束超过 33 年的执掌；CFO Colette Kress 出任临时 CEO，董事 Harvey Jones 成为 Nvidia 首位董事会主席。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T14:16:34.000Z","url":"https://x.com/rohanpaul_ai/status/2120883455689170968"},{"id":"a8s824c3xp0bij54fi8q9psm7","title":"黄仁勋因间谍丑闻辞去 Nvidia CEO 职务，公司市值蒸发 1.4 万亿美元","summary":"黄仁勋于 2026 年 11 月 12 日立即辞去 Nvidia CEO、总裁及董事会成员职务，此前《华尔街日报》报道董事会因两段婚外情（其中一段涉及疑似中国间谍）计划将其解雇。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T14:11:40.000Z","url":"https://the-decoder.com/jensen-huang-resigns-as-nvidia-ceo-after-espionage-scandal-wipes-out-1-4-trillion-in-market-value/"},{"id":"b79vyi335xo1r2u8eiza66a8r","title":"Nvidia CEO 黄仁勋因绯闻与间谍丑闻辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia 董事会宣布，联合创始人、总裁兼 CEO 黄仁勋在两段婚外情报道曝光后辞职，即日生效，自 2013 年起任职的 CFO Colette Kress 被任命为临时 CEO，并任命前 Synopsys CEO Harvey C. Jones 为公司历史上首任董事长。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T13:53:16.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031689/jensen-huang-nvidia-ceo-resigns"},{"id":"qsbjbz754aodhcijq56puh6va","title":"NVIDIA 宣布 CEO 变动：Jensen Huang 辞任，CFO Colette Kress 出任临时 CEO","summary":"NVIDIA 董事会宣布 Jensen Huang 即刻辞去总裁、CEO 及董事职务，CFO Colette Kress 被任命为临时 CEO，直至选定永久继任者，董事会已启动内外部人选遴选。","sourceName":"NVIDIA：Newsroom（RSS）","firstParty":true,"publishedAt":"2026-11-12T13:48:00.000Z","url":"https://nvidianews.nvidia.com/news/nvidia-announces-ceo-transition"},{"id":"mo0q79b9m2krn2wunnm5blw48","title":"郭明錤谈黄仁勋出轨丑闻：英伟达或需降低对其决策依赖并布局接班计划","summary":"天风国际分析师郭明錤在 X 平台发文评黄仁勋出轨丑闻，认为黄的价值在于把工程团队认为可行的技术转化为全公司愿意投入资源、承担风险并交付的产品，带动供应链订单能见度与竞争对手跟进。他从公开信息判断黄仁勋似乎很难全身而退，建议英伟达阶段性降低对黄个人的决策依赖并布局接班计划，其后续新品研发效率与竞争对手回应将是观察 AI 产业发展和投资趋势的重点。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T04:15:28.377Z","url":"https://www.ithome.com/1/026/027.htm"},{"id":"b0is4k552g0vme6l74e8z1lhw","title":"Gary Marcus 评 WSJ 报道 Nvidia 正准备解雇 CEO 黄仁勋","summary":"Gary Marcus 引述《华尔街日报》报道称，Nvidia 正准备解雇 CEO 黄仁勋，起因是公司调查其与一名被指为中国间谍的女性的婚外情。作者认为黄仁勋是整个循环融资的主导者，若其离任这些安排可能崩塌，并质疑代理 CEO 是否会兑现 Nvidia 承诺给 Anthropic 的数十亿美元 IPO 投资；盘后股价已下跌。","sourceName":"Gary Marcus：The Road to AI We Can Trust（RSS）","firstParty":false,"publishedAt":"2026-11-11T23:53:06.000Z","url":"https://garymarcus.substack.com/p/jensen-is-reportedly-about-to-get"},{"id":"i1hiziogjyvjvclikqylj5p2p","title":"黄仁勋丑闻时间线：婚外情、疑似中国间谍与Nvidia董事会罢免传闻","summary":"Nvidia CEO 黄仁勋公开承认婚外情，其绯闻对象、Megaspeed 高管 Alice Huang 被美国官员怀疑是中国间谍。纽约时报称黄仁勋还与直接向他汇报的 Nvidia 医疗健康副总裁 Kimberly Powell 存在婚外关系，Nvidia 董事会正准备罢免他，股价盘后下跌。国会计划传唤黄仁勋就此事作闭门说明。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T23:50:00.000Z","url":"https://techcrunch.com/2026/11/11/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"aoxmmcsudy1gf9xmti7slu1wd","title":"WSJ 报道 Nvidia 董事会接近决定是否罢免 CEO 黄仁勋","summary":"WSJ 报道，Nvidia 董事会此前公开支持黄仁勋，如今接近决定是否罢免这位创始人 CEO。起因是黄仁勋与一名被指为中国情报人员的女子交往，随后又曝出与一名 Nvidia 员工的第二段婚外情；周日开始独立调查时董事会表示没有理由认为 Nvidia 机密泄露。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T23:43:05.000Z","url":"https://x.com/rohanpaul_ai/status/2120663635479625930"},{"id":"vyp3tt502r42oxb18k4b663hi","title":"黄仁勋\"蜜罐\"丑闻背后：半导体行业高管行为问题是否更普遍？","summary":"Heron Intelligence CEO Nate Singer 在黄仁勋\"蜜罐\"丑闻后表示，半导体行业存在多起未曝光的类似高管行为案例，他已看到至少三份相关报告，并怀疑更多案例未被上报。Singer 称业内许多高管知晓此类行为却实际上予以纵容，涉事人员\"已嵌入这些公司\"。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-11T16:16:07.000Z","url":"https://techcrunch.com/2026/11/11/is-jensen-huangs-bad-behavior-more-commonplace-than-it-seems/"},{"id":"x7y9eom67zy7rs1vzn6sijizd","title":"ElevenLabs 纽约峰会发布多项更新：Interaction Engine、ElevenAgents 升级与 ElevenAI","summary":"ElevenLabs 在纽约峰会宣布多项发布，定位为构建 AI 的交互层。","sourceName":"ElevenLabs：Blog（网页）","firstParty":true,"publishedAt":"2026-11-11T12:00:00.000Z","url":"https://elevenlabs.io/blog/nyc-summit"},{"id":"k0s9asp7ahp38drtj69gi5lye","title":"英伟达CEO绯闻或波及芯片业","summary":"《华尔街日报》：出口管制支持者以这一事件为证，佐证他们对漏洞的警告\n\n“英伟达CEO的绯闻可能给这家全球顶级芯片设计公司乃至整个行业带来商业后果。\n\n尽管许多议员在提出法案时都提到了英伟达，但这些提案可能伤及其他芯片公司，包括英伟达的竞争对手AMD，甚至微软和OpenAI这类正试图在海外建设数据中心的科技巨头。”","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-11T05:42:06.000Z","url":"https://x.com/rohanpaul_ai/status/2120391599264063648"},{"id":"ggty0pffnixa85pbbyxk826ug","title":"FT 曝 Alice Huang 借 Megaspeed 走私 Nvidia 芯片","summary":"FT 发文披露 Alice Huang 与秘密男友兼商业伙伴 Kang Wei 运营新加坡公司 Megaspeed，用阿里巴巴的资金向被美国出口规则限制的中国客户出租 Nvidia 芯片。她改名 Alice Wong 并把妹妹安插进公司董事会以隐藏实际控制人，美国情报部门认为她在接近黄仁勋期间为中国从事间谍活动，新加坡调查 Megaspeed 芯片走私后她已消失。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T20:28:14.000Z","url":"https://x.com/rohanpaul_ai/status/2120252212551332311"},{"id":"lmoed4ffl87b0bpfvt1lzsp1g","title":"黄仁勋被曝与疑似中国间谍有染，或危及美国 AI 领先地位","summary":"英伟达 CEO 黄仁勋承认与一名疑似中国间谍的女性有染，事件可能冲击整个美国 AI 产业并危及国家安全。专家向 The Verge 表示，若中国借此获得英伟达芯片，美国在 AI 上的领先优势\"可能在数周或数月内消失\"；与这名疑似间谍有关联的公司据称已促成至少 70 亿美元的英伟达芯片销往中国。消息曝光后英伟达股价下跌。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T19:04:05.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1031063/jensen-huang-ai-race-us-china-spy"},{"id":"gqzca7y2h3m9p0fxtj60m4i1t","title":"Ed Zitron 长文剖析黄仁勋丑闻与 NVIDIA 疑似借 Megaspeed 向中国走私 GPU","summary":"Ed Zitron 长文梳理黄仁勋承认与 Megaspeed CEO Alice Huang 的婚外情事件，并整合 Bloomberg、纽约时报、金融时报与 Culper Research 的报道，指 Megaspeed 疑似作为转口实体将 NVIDIA GPU 非法流入中国。","sourceName":"Ed Zitron 长文 / Where’s Your Ed At（RSS）","firstParty":false,"publishedAt":"2026-11-10T17:43:27.000Z","url":"https://www.wheresyoured.at/jensens-bizarre-adventure/"},{"id":"nakew5hejxet8jnydy0h37b1q","title":"英伟达 CEO 黄仁勋承认婚外情，涉疑似中国间谍事件时间线","summary":"英伟达 CEO 黄仁勋 11 月 8 日向员工公开承认婚外情，并称此事关联新闻报道中的国家安全担忧，英伟达董事会已启动独立调查，公司股价次日下跌超 5%。美方官员认为其婚外情对象、Megaspeed 高管 Alice Huang 为中国间谍，Megaspeed 过去两年据称采购了 48 亿美元英伟达芯片。三名共和党委员会主席已要求黄仁勋就中国获取美国技术风险进行闭门简报。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-10T17:04:19.000Z","url":"https://techcrunch.com/2026/11/10/nvidia-ceo-jensen-huangs-affair-with-alleged-chinese-spy-a-timeline/"},{"id":"f1z5v9nswvnu4w2plxd4tg22t","title":"The Information 报道称与英伟达 CEO 黄仁勋相关人士向中国买家转手 75 亿美元硬件","summary":"据 The Information 报道，与英伟达 CEO 黄仁勋有染的 Alice Huang（无亲属关系）与丈夫和姐姐在中国和新加坡建立采购网络，涉资 75 亿美元。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-10T14:33:22.000Z","url":"https://x.com/rohanpaul_ai/status/2120162909422780789"},{"id":"z68n80gno9fz2iwdgj4wr9tyw","title":"黄仁ullah承认婚外情，Nvidia 董事会调查对方是否为中国国安部工作","summary":"周日黄仁ullah向全体 Nvidia 员工发邮件承认与 Megaspeed 高管 Alice Huang 的婚外情，其董事会已启动调查，核查该女士是否为中国国家安全部工作。Megaspeed 这家被怀疑向中国走私 Nvidia 芯片的新加坡云公司仍在继续采购芯片。","sourceName":"ChinaTalk（RSS）","firstParty":false,"publishedAt":"2026-11-10T12:28:08.000Z","url":"https://www.chinatalk.media/p/the-spy-who-leased-me"},{"id":"kci32x4hgxrdl0v5o4xrjlxri","title":"The Verge 梳理黄仁勋与 Megaspeed 高管丑闻对 Nvidia 出口管制游说的影响","summary":"The Verge 依据《纽约时报》等报道梳理 Nvidia CEO 黄仁勋与新加坡云服务商 Megaspeed 高管 Alice Huang 的婚外情风波。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:51:58.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030328/what-could-china-get-from-jensen-huang"},{"id":"t5mqlkgq1zlspdsk77jrx1ho5","title":"Trump 就间谍指控表态支持 Nvidia CEO 黄仁勋","summary":"Trump 在与 Nvidia CEO 黄仁勋就间谍指控谈话后公开为其辩护，称黄仁勋告诉他从不认识那名女性是间谍，并表示相信他。Trump 称黄仁勋是高素质的人，提到其芯片领先十年、因复杂度难以被复制，并称相信黄仁勋因家人而深感痛苦。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-09T23:12:09.000Z","url":"https://x.com/rohanpaul_ai/status/2119931075325759514"},{"id":"lzsihkjga6ini01aqrzcuvtaw","title":"Nvidia CEO 黄仁勋因间谍与婚外情丑闻辞职，CFO Colette Kress 出任临时 CEO","summary":"Nvidia CEO、总裁兼联合创始人黄仁勋在承认与 Megaspeed 高管 Alice Huang 的婚外情后辞职，CFO Colette Kress 出任临时 CEO。《纽约时报》周三报道称，还存在另一段与直接向他汇报的 Nvidia 高管的婚外情证据，当晚董事会会议以黄仁勋辞职告终。此前有报道指出，美国情报部门自去年起认定 Alice Huang 为中国国家安全部间谍。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T23:07:59.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1030422/nvidia-jensen-huang-ai-china-alice-huang"},{"id":"zqvokl37rwbvoxzfk3c2v7964","title":"做空机构 Culper Research 曾在丑闻爆发前六个月提示 Nvidia CEO 与疑似中国间谍的关系","summary":"Nvidia 间谍丑闻爆发前六个月，做空机构 Culper Research 已在 5 月 13 日报告中质疑 CEO 黄仁勋与 Megaspeed 高管 Alice Huang 关系“异常密切”。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T22:46:09.000Z","url":"https://techcrunch.com/2026/11/09/a-short-seller-flagged-nvidia-ceos-ties-to-a-suspected-chinese-spy-six-months-before-the-scandal/"},{"id":"wtp3nz2jg6cfwlvn12lqrucy7","title":"黄仁勋因个人风波退出 ElevenLabs Summit 等演讲活动","summary":"TechCrunch 报道，Nvidia CEO 黄仁勋退出本周三在纽约举行的 ElevenLabs Summit，并取消了包括 Anthropic CEO Forum 在内的其他演讲安排，ElevenLabs 周一已确认。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-09T20:09:06.000Z","url":"https://techcrunch.com/2026/11/09/jensen-huang-pulls-out-of-elevenlabs-summit-amid-nvidia-controversy/"}]},"2ff1f46f-7e98-4965-a5b2-87329632ca5d":{"publicId":"2ff1f46f-7e98-4965-a5b2-87329632ca5d","title":"Google 发布 Gemini 4 Hydrogen，接入搜索与编程工具","status":"active","sourceCount":25,"reportCount":50,"firstReportAt":"2026-11-11T16:00:00.000Z","latestAt":"2026-11-13T22:05:33.000Z","latest":"Gemini 4 Hydrogen 从创意到成片","digest":"Google DeepMind 发布 Gemini 4 Hydrogen，定位为快速执行日常编码与智能体工作流的模型，与主打深度推理的 Carbon、Argon 同属 Gemini 4 系列。Google 称这是 Search 迄今最大的模型升级，已向全球所有用户开放；该模型同时成为 Gemini Managed Agents 中 Antigravity 智能体的默认模型，并已上线 Cursor 和 Cognition 的 Devin Desktop、Devin CLI，OpenClaw 也称已可使用。Ars Technica 称它取代了此前广泛使用的 Gemini 3.8 Flash，且上线即开放，不像 Argon、Carbon 那样分阶段推送。\n\n使用范围按用户类型区分：所有用户可在 Gemini 应用、Google Search 和 Google AI Studio 访问；付费 Google AI Pro 和 Ultra 订阅者还可在 Google Antigravity、Chrome 中的 Gemini 和 Google Sheets 中的 Gemini 使用；开发者和企业可通过各档 Gemini API、Android Studio 及 Gemini for business 使用。免费用户在 Gemini 应用中需通过自动模型选择，在适合该提示词的场景下才会用到 Hydrogen。定价为 100 万 token 上下文窗口内统一计价：输入每百万 token 1.50 美元，输出每百万 token 7.50 美元。\n\n第三方评测机构 Artificial Analysis 称，该模型新增的 xhigh 推理档在 Intelligence Index 得 54 分，比 Claude Sonnet 5.5 (max) 和 GPT-6.1 Sol (max) 低 1 分；每任务成本约为 Sonnet 的 32%，但约为 GPT-6.1 Sol 的 2.5 倍。该机构另称 Hydrogen 在 AA-Robotics v0.1 中排第四，是排名最高的 Google 模型，落后于 Claude Fable 5.2、GPT-6 Astra 和 GPT-6.1 Sol。Cursor 称该模型在其默认 effort 下 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%；Cognition 称其在 FrontierCode 2.0 得 38.2%，仅次于 GPT-6.1 Sol；Arena 榜单显示 Gemini 4 Hydrogen (High) 首次进入 Code Arena: WebDev 第 10 名，得 1703 分。","digestUpdatedAt":"2026-11-13T22:36:16.605Z","reports":[{"id":"xj28n9bhcnubeongt22akjetp","title":"Gemini 4 Hydrogen 从创意到成片","summary":"用 Gemini 4 Hydrogen 把创意变成成片视频。\n\n借助自定义技能和简单简报，Gemini 4 Hydrogen 制作了一支关于元素“氢”的宣传短片，取材公共领域档案影像，并将其剪辑成一段连贯的成片，配有清晰的旁白。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-13T22:05:33.000Z","url":"https://x.com/GeminiApp/status/2121363868425306372"},{"id":"is2tfl9q4lfy999n19vy29p0m","title":"Google 本周发布汇总：TPU 与 Gemini 4","summary":"本周 @google 我们发布了这些内容\n\n周一：两款新一代第八代 TPU\n周二：Gemini 4 Carbon\n- AlphaProof Code 验证了 Signal 协议\n- Gemini Robotics 2.5\n周三：用于疾病研究的 AlphaGenome 2\n- AI Studio 中的 Gemini Decisions API\n周四：Gemini 4 Hydrogen\n- 智能眼镜开启预售\n周五：U2 新专辑（好吧，不是我们，但很令人兴奋！）\n\n继续前进！","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-13T20:23:09.000Z","url":"https://x.com/sundarpichai/status/2121338095664808238"},{"id":"aharkngusk0no7dmgd0kg5x8u","title":"Google 发布 Gemini 4 Hydrogen，速度比 Gemini 3.8 Flash 快 2.5 倍","summary":"Google DeepMind 发布闭源模型 Gemini 4 Hydrogen，定位编码与智能体工作流，速度比 Gemini 3.8 Flash 快 2.5 倍，Terminal-Bench 4.1 得分 57%（3.8 Flash 为 18.2%）。","sourceName":"MarkTechPost（RSS）","firstParty":false,"publishedAt":"2026-11-13T09:45:48.000Z","url":"https://www.marktechpost.com/2026/11/13/google-gemini-4-hydrogen/"},{"id":"g1i3oaaq9yrtsm2toewsuhcwk","title":"Gemini 4 Hydrogen 发布并已可在 OpenClaw 中使用","summary":"OpenClaw 转发官方消息：Google 推出 Gemini 4 Hydrogen，一个为让 Gemini 4 面向所有人而构建的高能力、快速模型。该模型面向 Google AI Studio、Gemini API、Gemini for business、Gemini 应用、Google Search 的所有层级开放，付费 Google AI Pro + Ultra 订阅者还可在 Google Antigravity 中使用；作者称其已可在 OpenClaw 中使用。","sourceName":"X：OpenClaw (@openclaw)","firstParty":false,"publishedAt":"2026-11-13T04:31:12.000Z","url":"https://x.com/openclaw/status/2121098531205501401"},{"id":"jk2j1qrls5xbfylot1i4nudhj","title":"Gemini 3.8 Flash 与 Hydrogen 动画对比","summary":"🌵 一览从 Gemini 3.8 Flash 到 Hydrogen 的演进：@Bhavani_00007 在两者上运行了相同的动画 3D 沙漠牧场提示词，Hydrogen 在不到 1 分钟内让场景生动呈现。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:02.000Z","url":"https://x.com/Google/status/2121037841287249920"},{"id":"k5e9f5e3c6xe1zza3n896s48r","title":"Gemini 4 Carbon 与 Hydrogen 协作打造飞蛾动画","summary":"🦋 @thtbee_ 在 @Antigravity 中将我们最新的两个模型搭配使用，让一只绯红色飞蛾活了起来：\n\nGemini 4 Carbon 调度了一支由 Hydrogen 工作单元组成的 /swarm，创作出一段带有大气视觉效果与声音的交互式动画。\n\n随后，Hydrogen 还录制了演示视频。\nhttps://x.com/thtbee_/status/2120958666480513310/video/1","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:02.000Z","url":"https://x.com/Google/status/2121037839563730994"},{"id":"ezf7jqy3z5guwnvf7h2p8734y","title":"Google Antigravity 演示 Hydrogen 通勤场景","summary":"🌃 @kimmonismus 在 @Antigravity 中用高思考模式的 Hydrogen 打造了我们理想的通勤场景。\n\n欣赏这段穿越 Three.js 霓虹天际线的流畅飞行。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:01.000Z","url":"https://x.com/Google/status/2121037833699995729"},{"id":"u38hqxar8y2h8tqj2lrpmatbl","title":"Gemini 应用用 Hydrogen 设计 3D 锦鲤池","summary":"🐠@IamEmily2050 在 @Geminiapp 中使用 Hydrogen 设计了一个 3D 体素锦鲤池，配有红色宝塔、樱花和灯笼点缀的桥梁。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:01.000Z","url":"https://x.com/Google/status/2121037835629109486"},{"id":"lf2ylaegvpxzrjrjflaqjqiz2","title":"Google 展示 Gemini 4 Hydrogen 开放后用户的创意构建案例","summary":"Google 表示 Gemini 4 Hydrogen 已向所有人开放，并汇总了用户在 @GeminiApp、@Antigravity 和 @GoogleAIStudio 上基于模型实现的各类“what if”创意构建。帖中举例 @LuminaBench 制作的 3D 水上飞机从日出飞到夜晚的场景，并预告后续将分享更多作品。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T00:30:00.000Z","url":"https://x.com/Google/status/2121037830797271522"},{"id":"ajlka18ww5d31h5ezjf16r801","title":"Google 发布 Gemini 4 Hydrogen，Simon Willison 梳理 Gemini 4 定价并实测对比","summary":"Google 发布 Gemini 4 家族最低价型号 Gemini 4 Hydrogen，定价 $1.50/$7.50（每 M token 输入/输出），作者 Simon Willison 称 Gemini 4 定价令人困惑。","sourceName":"Simon Willison 博客","firstParty":false,"publishedAt":"2026-11-12T22:55:19.000Z","url":"https://simonwillison.net/2026/Nov/12/llm-gemini/"},{"id":"w61lggu0l1pijph9baxgv21z2","title":"Gemini 4 Hydrogen 用表格画动态风景","summary":"我们大多数人打开 Google Sheets 是为了做预算、跟踪表和表格。借助 Gemini 4 Hydrogen，我们想看看它能否反过来绘制一幅动态风景 🍃\n\n在 Google @Antigravity 中，Hydrogen 负责编写代码来绘制并动画化数千个单元格——创造出海岸列车、飘动的云朵和飘落的秋叶，并在电子表格内逐帧重新计算。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T22:17:02.000Z","url":"https://x.com/Google/status/2121004369617485896"},{"id":"dhccssumshi2lie122qh66tgp","title":"Google 发布 Gemini 4 Hydrogen，提升复杂问题理解并成为 AI Mode 默认模型","summary":"Google 发布 Gemini 4 Hydrogen 模型，称其能更好地处理多部分问题、难以理解的拼写错误和高度具体请求，可拆解问题并逐部分回答。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T21:55:32.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1032505/google-search-ai-mode-gemini-4-hydrogen"},{"id":"cy8ycgy2ijidcqfu9ubcc2kd2","title":"Gemini 4 Hydrogen 在 AA-Robotics 排名第四","summary":"Gemini 4 Hydrogen 是 AA-Robotics v0.1 上排名最高的 Google 模型，总排名第四，落后于 Claude Fable 5.2（75）、GPT-6 Astra（69）和 GPT-6.1 Sol（65）\n\nHydrogen 对自己的表现非常诚实，指出倒饮料时有一点洒出，整理积木时有一个盖子没盖好","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-12T21:40:31.000Z","url":"https://x.com/ArtificialAnlys/status/2120995180891508833"},{"id":"zlbngirpqifhhi3bd5pbmixu4","title":"Gemini 4 Hydrogen 今日起向全球所有用户推送","summary":"Google Gemini 宣布 Gemini 4 Hydrogen 今日起向全球所有用户推送，覆盖桌面、移动和网页端。免费用户无需单独选择模型，当提示词适合该模型时可通过自动模型选择使用它，详情见 https://goo.gle/4AxH40q。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T20:50:50.000Z","url":"https://x.com/GeminiApp/status/2120982674638864797"},{"id":"y0y7mh858hig08jz41nfdczcu","title":"Gemini 4 Hydrogen 实时模拟光折射","summary":"在完成创建交互式 3D 水和玻璃可视化工具的任务时，Gemini 4 Hydrogen 能够使用 WebGL2 和纯数学实时模拟光的折射、反射和色散。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T20:49:58.000Z","url":"https://x.com/GeminiApp/status/2120982456203694352"},{"id":"u7yh59ito20pqcy3kfrg1jao9","title":"Google 发布 Gemini 4 Hydrogen，评测得分超过更大的 Argon","summary":"Google 发布 Gemini 4 Hydrogen，主打快速低价处理日常任务，在 Artificial Analysis Intelligence Index 上默认 high 档得 51 分、最高 xhigh 档得 54 分，超过 Gemini 4 Argon 的 50 分。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T19:58:43.000Z","url":"https://the-decoder.com/googles-gemini-4-hydrogen-outscores-the-bigger-argon-just-four-weeks-after-its-launch/"},{"id":"glx90o1i9stshq4vwsxdsguy5","title":"Google 发布 Gemini 4 Hydrogen 并将其接入 Search 提升复杂问题回答","summary":"Google 发布 Gemini 4 Hydrogen 模型并将其接入 Search，称这是 Search 迄今最大的一次模型改进。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T19:27:45.000Z","url":"https://techcrunch.com/2026/11/12/googles-latest-search-upgrade-promises-better-answers-to-your-most-complicated-questions/"},{"id":"w1u3ixmq8qb8g20v2o8yfebpw","title":"Google 在搜索中引入 Gemini 4 Hydrogen","summary":"Google 官方宣布 Gemini 4 Hydrogen 已进入 Google Search，并提供链接 goo.gle/4AqQVF5 供用户了解更多信息。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T19:23:35.000Z","url":"https://x.com/Google/status/2120960717071474748"},{"id":"pplqpkkb0a59joi6llhtmrgff","title":"Google Search 接入 Gemini 4 Hydrogen 并向全球用户推送","summary":"Google 宣布 Search 迎来迄今最大模型更新，接入 Gemini 4 Hydrogen，今日起向全球所有用户推出。更新包括更好理解多部分复杂问题、支持错别字并覆盖所有 AI Mode 语言；回答采用带图片、对比表的视觉化布局；升级 query fan-out，并行子主题查询以链接更多相关网页。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T19:23:34.000Z","url":"https://x.com/Google/status/2120960715011883148"},{"id":"r03z6qalcfw99hwf8jq8b5mxb","title":"Google 发布 Gemini 4 Hydrogen，取代 Gemini 3.8 Flash","summary":"Google 发布 Gemini 4 Hydrogen，取代生态内广泛使用的 Gemini 3.8 Flash，且开放程度远高于此前 Argon、Carbon 的分阶段策略，上线即对用户开放。","sourceName":"Ars Technica：AI（RSS）","firstParty":false,"publishedAt":"2026-11-12T19:23:03.000Z","url":"https://arstechnica.com/google/2026/11/google-rolls-out-gemini-4-hydrogen-finally-replacing-3-8-flash/"},{"id":"o8coj46233j11jhise87m8gza","title":"Gemini 4 Hydrogen (High) 登上 Code Arena: WebDev 第 10 名，得 1703 分","summary":"Arena 官方榜单显示，Google DeepMind 的 Gemini 4 Hydrogen (High) 首次进入 Code Arena: WebDev 排行第 10 名。","sourceName":"X：Arena (@arena)","firstParty":false,"publishedAt":"2026-11-12T19:05:40.000Z","url":"https://x.com/arena/status/2120956209725661670"},{"id":"qcfuv50f2bxz6tv32dtblc88x","title":"谷歌发布 Gemini 4 Hydrogen 模型，主打日常编程与智能体工作流","summary":"谷歌推出 Gemini 4 Hydrogen 模型，面向日常编码和智能体工作流，输入每百万 Tokens 1.50 美元、输出 7.50 美元，覆盖 100 万 Token 上下文无阶梯计价。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-12T18:50:00.073Z","url":"https://www.ithome.com/1/026/446.htm"},{"id":"uu2pim7p0lb9lhqcrvg7v3zgu","title":"Gemini 4 Hydrogen 上线 Devin","summary":"Gemini 4 Hydrogen 现已在 Devin Desktop 和 Devin CLI 上线。\n\n在 FrontierCode 2.0 上——这是我们用来基于质量和可合并性评估模型在真实工程任务中表现的基准——Gemini 4 Hydrogen 得分 38.2%，仅次于 GPT-6.1 Sol。","sourceName":"X：Cognition (@cognition)","firstParty":false,"publishedAt":"2026-11-12T18:44:28.000Z","url":"https://x.com/cognition/status/2120950876248641588"},{"id":"mt013742fhedisepp2i31h1r4","title":"Gemini 4 Hydrogen 上线 Cursor，CursorBench 得分 54.3%","summary":"作者以「爱好包括制作 og:images」调侃，配图为 CursorBench 4.0 的模型散点图；其引用 Cursor 官方内容称 Gemini 4 Hydrogen 现已在 Cursor 上线，默认 effort 下 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%。","sourceName":"X：Matt Palmer（SpaceXSI，Grok Bot） (@mattyp)","firstParty":false,"publishedAt":"2026-11-12T18:22:08.000Z","url":"https://x.com/mattyp/status/2120945253666762973"},{"id":"leysijsx8660t8pwgnnslip9g","title":"Cursor 公布 Gemini 4 Hydrogen 定价","summary":"Gemini 4 Hydrogen 定价为每百万输入 token 1.50 美元，每百万输出 token 7.50 美元。\n\n对比各档 effort 水平：https://cursor.com/evals?v=1","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-12T18:19:44.000Z","url":"https://x.com/cursor_ai/status/2120944651960291781"},{"id":"vwpr1h68drk55b95gmxib4f4q","title":"Gemini 4 Hydrogen 现已登陆 Cursor，CursorBench 得分 54.3%","summary":"Cursor 宣布 Gemini 4 Hydrogen 现已可用。其默认 effort 下在 CursorBench 得分 54.3%，高于 Gemini 3.8 Flash 的 39.6%。","sourceName":"X：Cursor (@cursor_ai)","firstParty":false,"publishedAt":"2026-11-12T18:19:41.000Z","url":"https://x.com/cursor_ai/status/2120944639633211619"},{"id":"q7eh6zetx4dgeec6vz7r00onv","title":"Gemini 4 Hydrogen 发布，已上线 Gemini App","summary":"Google Labs VP Josh Woodward 宣布发布 Gemini 4 Hydrogen，现已可在 Gemini App 中使用。原文称该模型速度快、更智能、是一次大幅提升，未给出具体性能数据或技术细节。","sourceName":"X：Josh Woodward (@joshwoodward, Google Labs VP)","firstParty":false,"publishedAt":"2026-11-12T18:10:15.000Z","url":"https://x.com/joshwoodward/status/2120942262054232392"},{"id":"e3o0ut2he1m7y82w20od4ed48","title":"Gemini 4 Hydrogen 任务速度提升 2.5 倍","summary":"仅作一项对比，Gemini 4 Hydrogen 完成任务的速度比 3.8 Flash 快 2.5 倍，同时智能程度高得多，编造内容还少了 5 倍。\n\n这是个好模型 ：)","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:09:12.000Z","url":"https://x.com/OfficialLoganK/status/2120941998014390392"},{"id":"w3iirjuk8jtt1lka51a28bwv2","title":"Gemini 4 Hydrogen 开始向所有人推送，覆盖 Gemini App、搜索与 Gemini API","summary":"Google 宣布 Gemini 4 Hydrogen 即日起开始推送。所有用户可在 Gemini App、Google Search 和 Google AI Studio 使用；AI Pro 和 Ultra 订阅者还可用于 Antigravity、Chrome 中的 Gemini 和 Google Sheets 中的 Gemini；开发者和企业可在 Google AI Studio、AndroidStudio 及各档 Gemini API 使用。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:10.000Z","url":"https://x.com/Google/status/2120941989948457042"},{"id":"t1zssrg26pwcowrqz6buo5qp9","title":"Google 发布 Gemini 4 Hydrogen：智能、速度与可靠性大幅提升","summary":"Google 发布 Gemini 4 Hydrogen，称其在默认 high thinking 下于 Artificial Analysis 智能指数上超过 Argon，xhigh 下更高，且同类任务完成更快。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:09.000Z","url":"https://x.com/Google/status/2120941986895319158"},{"id":"clge7zh429cqvd5tz2zsr908w","title":"Google 发布 Gemini 4 Hydrogen，主打日常编码与智能体工作","summary":"Google 发布 Gemini 4 Hydrogen，面向日常编码和智能体工作，强调速度与效率。该模型提供 4 个思考级别，可独立使用或与 Carbon 和 Argon 协同，比 3.8 Flash 快 2.5X，官方称在其同级中领先竞争模型。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:08.000Z","url":"https://x.com/Google/status/2120941982004523367"},{"id":"mlams5mulqbf16g7tini41vf3","title":"Google 介绍 Hydrogen 四档思考级别与 Antigravity Orchestrator 多模型协作","summary":"Google 介绍 Hydrogen 提供低、中、高和新增 xhigh 四个思考级别，按可预期的方式权衡智能、延迟和 token 用量。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-12T18:09:08.000Z","url":"https://x.com/Google/status/2120941984148041901"},{"id":"ajvxvhu8bh001pourbhhjl0ir","title":"Artificial Analysis 评测 Gemini 4 Hydrogen：智能指数 54，接近 Sonnet 5.5 且成本约其 32%","summary":"Artificial Analysis 评测 Google 新发布的 Gemini 4 Hydrogen：新增 xhigh 推理档在 Intelligence Index 得 54 分，比 Claude Sonnet 5.5 (max) 和 GPT-6.1 Sol (max) 低 1 分，每任务成本约为 Sonnet 的 32%，但约为 GPT-6.1 Sol 的 2.5 倍。","sourceName":"X：Artificial Analysis (@ArtificialAnlys)","firstParty":false,"publishedAt":"2026-11-12T18:07:16.000Z","url":"https://x.com/ArtificialAnlys/status/2120941511223185722"},{"id":"psfuehcy5xg07khe2ggyazuhq","title":"Google 发布 Gemini 4 Hydrogen，与 Carbon、Argon 一起开启 Gemini 4 时代","summary":"Google 发布 Gemini 4 Hydrogen，与 Carbon 和 Argon 一起完整开启 Gemini 4 时代。作者 Logan Kilpatrick 表示自己已每日使用该模型，Google 内部有数千人也在使用，并给出博客链接 https://blog.google/innovation-and-ai/models-and-research/gemini-models/introducing-gemini-4-hydrogen/。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:06:55.000Z","url":"https://x.com/OfficialLoganK/status/2120941424028029030"},{"id":"ybgw60e8kl0ckmqzx8x4n18q6","title":"Gemini 4 Hydrogen 开始向全球所有用户推送","summary":"Google Gemini 宣布 Gemini 4 Hydrogen 今日开始向全球所有用户推送，覆盖桌面、移动端和网页。免费用户可通过自动模型选择在适合该提示词的场景下使用 Gemini 4 Hydrogen，详情见 https://goo.gle/4AxH40q。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:06:49.000Z","url":"https://x.com/GeminiApp/status/2120941398971318410"},{"id":"jpbfn2g31iz5iovg126icbq7l","title":"Gemini Hydrogen 加速交互原型迭代","summary":"日常原型设计与迭代。\n\n在探索和测试想法时，Hydrogen 能用更少的提示词生成干净、可用的布局，让交互项目的快速原型设计与优化变得轻松。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:05:54.000Z","url":"https://x.com/GeminiApp/status/2120941167584108776"},{"id":"rtug94ind3nuemcslhudu9ver","title":"Gemini 推出 Hydrogen 逐步拆解任务并调用应用完成待办","summary":"Google Gemini 官方宣布 Hydrogen 功能，将用户目标逐步拆解，从上传内容、Gmail、Google Drive 及 Airtable、Dropbox 等 Connected Apps 拉取相关上下文。在 Gemini 中开始任务时，它会更频繁调用合适的工具和技能，帮助更快完成待办清单。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:05:31.000Z","url":"https://x.com/GeminiApp/status/2120941072050471156"},{"id":"rt584cexu9fp97te4mb91obzr","title":"Google 发布 Gemini 4 Hydrogen","summary":"Google 发布 Gemini 4 Hydrogen，定位能力强且快速，让 Gemini 4 覆盖更多用户。该模型向 Google AI Studio、Gemini API、Gemini for business、Gemini 应用、Google Search 全量开放，付费 Google AI Pro + Ultra 订阅者可在 Google Antigravity 中使用。","sourceName":"X：Logan Kilpatrick (@OfficialLoganK)","firstParty":false,"publishedAt":"2026-11-12T18:05:02.000Z","url":"https://x.com/OfficialLoganK/status/2120940951292268640"},{"id":"rl7315tdvcb3agm4jz3u99e36","title":"Gemini Hydrogen 写作研究助手","summary":"开箱即用的写作、研究和日常工作。\n\nHydrogen 严格遵循你的语气、格式和具体规则，因此邮件草稿、学习指南、改写内容和复杂文档第一次就能直接使用。当你比较产品或综合密集材料时，它能整理出清晰的表格和可视化拆解，同时不遗漏关键细节。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:04:53.000Z","url":"https://x.com/GeminiApp/status/2120940914843795865"},{"id":"hd9c1p8riw1bpzs4yepq4h64d","title":"Hydrogen 用自然语言秒生成可交互代码","summary":"除了知识工作，Hydrogen 还将同样的速度和一次通过准确率带入实时编程，在数秒内把自然语言转化为可运行、可交互的代码。\n\n在 Geminisland 中可以看到它的实际表现——这是一个演示游戏，用户可以通过提示词，借助 Gemini API 上的 Hydrogen 实时在共享岛屿上构建新的 3D 体素结构。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:59.000Z","url":"https://x.com/GoogleAI/status/2120940684924403798"},{"id":"yg1hh9kmy0cj86m7f96b93pqn","title":"Google 发布 Gemini 4 Hydrogen，面向消费者和开发者全面开放","summary":"Google AI 宣布 Gemini 4 Hydrogen 从即日起可用。消费者可在 Gemini App 和 Google Search 中向所有用户开放，Google Sheets 中的 Gemini 面向 Google AI Pro 和 Ultra 订阅者；开发者和企业可通过 Google AI Studio 和 Android Studio 中的 Gemini API 构建，Google Antigravity 及 Gemini for business 面向付费 Pro 和 Ultra 订阅者。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:59.000Z","url":"https://x.com/GoogleAI/status/2120940686811750596"},{"id":"oyvn2ybcdov39n3frh8j060lg","title":"Google 发布 Gemini 4 Hydrogen，扩展 Gemini 4 模型系列","summary":"Google AI 宣布推出 Gemini 4 模型系列新成员 Gemini 4 Hydrogen，面向日常编码和智能体工作流，主打速度与效率。","sourceName":"X：Google AI (@GoogleAI)","firstParty":false,"publishedAt":"2026-11-12T18:03:58.000Z","url":"https://x.com/GoogleAI/status/2120940683233984862"},{"id":"xron978vcvj09ct0oz6iuvbrj","title":"Google 发布 Gemini 4 Hydrogen，主打日常快速帮助","summary":"Google 官方宣布 Gemini 4 Hydrogen 发布，面向所有人提供前沿智能和快速日常帮助。官方称它更能贴近用户指令行事、正确调用合适的工具，用更少的来回沟通获得可靠输出。","sourceName":"X：Gemini (@GeminiApp)","firstParty":false,"publishedAt":"2026-11-12T18:03:39.000Z","url":"https://x.com/GeminiApp/status/2120940601319260164"},{"id":"v26fsdyhbktgyuedmrx25p58y","title":"Google Gemini 开放推送，覆盖开发者、企业与普通用户渠道","summary":"Google DeepMind 宣布开始向各渠道推送：开发者可在 Google AI Studio、Android Studio 中用 Gemini API，付费 Google AI Pro 和 Ultra 订阅者可在 Google Antigravity 中使用；企业可通过 Gemini for business 和 Google Antigravity 部署；所有用户可在 Google Search 和 Gemini 应用模型下拉菜单中访问。详情见 https://goo.gle/4zDCs8N。","sourceName":"X：Google DeepMind (@GoogleDeepMind)","firstParty":false,"publishedAt":"2026-11-12T18:02:37.000Z","url":"https://x.com/GoogleDeepMind/status/2120940342505566438"},{"id":"ckdk8km29wmrflsa2fte7y832","title":"Google 发布 Gemini 4 Hydrogen，任务速度较 3.8 Flash 快 2.5 倍","summary":"Google 在 Carbon + Argon 之后发布 Gemini 4 Hydrogen，主打面向日常任务、编码和智能体工作流的速度与效率。相比 3.8 Flash 任务完成速度快 2.5 倍，并提供 4 档思考级别，用户只需为任务所需的推理深度等待和付费。模型今日起向 Google AI Studio 各档位、Gemini API、Gemini App、Search 以及 Google AI Pro 和 Ultra 订阅用户的 Google Antigravity 推出。","sourceName":"X：Sundar Pichai (@sundarpichai)","firstParty":false,"publishedAt":"2026-11-12T18:02:12.000Z","url":"https://x.com/sundarpichai/status/2120940236805169182"},{"id":"uy1ayrrlqx1snqsv4lub7whsa","title":"Google DeepMind 发布 Gemini 4 Hydrogen","summary":"Google DeepMind 发布 Gemini 4 Hydrogen，定位快速执行日常编码与智能体工作流，面向 Gemini API、AI Studio、Gemini 应用、Google Search 等全层级开放。","sourceName":"Google DeepMind：Blog（RSS）","firstParty":true,"publishedAt":"2026-11-12T18:00:50.000Z","url":"https://deepmind.google/blog/introducing-gemini-4-hydrogen/"},{"id":"v98atslrmng6mh1ez8840nx38","title":"Google Search 全面接入 Gemini 4 Hydrogen","summary":"Google 宣布 Gemini 4 Hydrogen 已向全球所有用户开放于 Google Search，称为 Search 迄今最大的模型升级。改进包括更细腻的意图理解与指令跟随、增强的 query fan-out 推理以覆盖更多相关子主题链接、更多图片、结构化回复和对比表等可视化响应，以及所有支持 AI Mode 语言下更细致的回答质量。","sourceName":"Google Blog：AI（RSS）","firstParty":true,"publishedAt":"2026-11-12T18:00:00.000Z","url":"https://blog.google/products-and-platforms/products/search/gemini-4-hydrogen-search-upgrade/"},{"id":"e1tuwzogxnhwavo3muu1ivhdy","title":"Gemini 4 Hydrogen (gemini-4-hydrogen) 正式可用并成为 Antigravity 智能体默认模型","summary":"Google 在 Gemini API 更新日志中宣布 Gemini 4 Hydrogen (gemini-4-hydrogen) 正式可用 (GA)，面向日常编码和智能体工作流提供速度与效率。","sourceName":"Gemini API：更新日志（网页）","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://ai.google.dev/gemini-api/docs/changelog#11-12-2026"},{"id":"v2mkjqo2c16gezu1uhe9d253j","title":"Gemini 4 Hydrogen vs 3.8 Flash 语音智能体实测：工具失败时零虚报且响应更快","summary":"LiveKit 工程师用故意设置失败的酒店预订工具，实测 Gemini 4 Hydrogen 与 gemini-3.8-flash 在语音智能体中的表现。54 份测试转写中 Hydrogen 零虚假工具报告，3.8 Flash 出现 2 次；Hygen 高档位下每轮首句延迟中位数 4,004 ms，比 3.8 Flash 默认档位的 5,212 ms 快 1.2 秒。","sourceName":"LiveKit 产品与工程博客","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://livekit.com/blog/gemini-4-hydrogen-first-impressions"},{"id":"d45gkw7az0yba8svolkwbyw8a","title":"Google 发布 Gemini 4 Hydrogen，主打快速执行与多模型协作","summary":"Google 发布 Gemini 4 Hydrogen，定位为面向日常编码与智能体工作流的快速执行模型，与主打深度推理的 Gemini 4 Carbon 和 Argon 互补，现已覆盖 AI Studio、Gemini API、Gemini 应用、Google Search 等全部层级。","sourceName":"Hacker News：AI 热帖","firstParty":false,"publishedAt":"2026-11-11T16:00:00.000Z","url":"https://blog.google/innovation-and-ai/models-and-research/gemini-models/introducing-gemini-4-hydrogen/"}]},"d6f453c1-9dce-4af5-8a9a-ff7b8642493c":{"publicId":"d6f453c1-9dce-4af5-8a9a-ff7b8642493c","title":"微软365故障波及Claude，Anthropic通报中断","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-11-13T13:10:18.303Z","latestAt":"2026-11-13T13:10:18.303Z","latest":"微软 Microsoft 365 大范围故障波及 Claude，Anthropic 连发多条状态通报","digest":"微软 Microsoft 365 出现近年最严重的服务故障之一，Exchange Online、Outlook、SharePoint 及部分 Teams 中断近一天半，微软高管为此致歉。Anthropic 称 Claude 部分服务的中断源于 Microsoft 365 连接问题，并通过 Claude Status 页面陆续发布多条通报。\n\n目前公开的信息只说明 Anthropic 将故障归因于微软侧连接，Claude 受影响的具体范围和恢复时间未在通报中给出。","digestUpdatedAt":"2026-11-13T13:26:00.388Z","reports":[{"id":"h2nxkfqpvkcqzof1dlta9j5w0","title":"微软 Microsoft 365 大范围故障波及 Claude，Anthropic 连发多条状态通报","summary":"微软 Microsoft 365 出现近年最严重的服务故障之一，Exchange Online、Outlook、SharePoint 及部分 Teams 中断近一天半，微软高管为此致歉。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-13T13:10:18.303Z","url":"https://www.ithome.com/1/026/948.htm"}]},"e5b4067f-6f2e-4f04-8799-21e4fbd9b590":{"publicId":"e5b4067f-6f2e-4f04-8799-21e4fbd9b590","title":"OpenAI推出ChatGPT Wallet，智能体可代用户购物","status":"active","sourceCount":9,"reportCount":10,"firstReportAt":"2026-11-13T15:00:00.000Z","latestAt":"2026-11-13T20:45:10.000Z","latest":"OpenAI 推出 ChatGPT Wallet，让 Dots 智能体代用户购物","digest":"OpenAI推出ChatGPT Wallet，让ChatGPT Work、Codex和dots中的智能体在用户批准下完成购买，并沿用用户现有银行卡的保护机制。该功能由OpenAI与美国运通、万事达卡和Visa合作开发，初期不向交易收取佣金。\n\n初期仅向限量美国年满18岁的ChatGPT Pro订阅用户开放，且需使用美国账单地址并绑定美国发行的合资格卡。关于卡组织范围，TechCrunch称支持Visa、万事达卡和美国运通，The Verge则称还包括Chase。TechCrunch报道称，用户可让名为dot的智能体帮助决定买什么，再由其代为完成结账。\n\nChatGPT官方账号称，智能体支付时不会接触用户的实际卡号信息，每笔购买都需通过安全检查。X用户Rohan Paul称，每次购买需生物识别批准，智能体以替代真实卡号的token支付，卡号对商户和智能体均不可见；他还称OpenAI计划日后允许用户设置消费限额和类别、完全委托购买。The Verge也引述OpenAI称，未来用户可设定消费限额、购买类别或时间段等参数，并预先批准这些购买。这些均为计划中的说法，尚未落地。","digestUpdatedAt":"2026-11-13T21:42:56.903Z","reports":[{"id":"e4m14f9vuxsp5zvwm9yryrhgw","title":"OpenAI 推出 ChatGPT Wallet，让 Dots 智能体代用户购物","summary":"OpenAI 推出 ChatGPT Wallet，即日起面向美国 18 岁及以上 ChatGPT Pro 订阅用户开放，支持美国发行的 American Express、Chase、Mastercard 和 Visa 合资格卡。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T20:45:10.000Z","url":"https://www.theverge.com/ai-artificial-intelligence/1033425/openai-chatgpt-wallet"},{"id":"e2adsv8qtekpt20mxqjhmxe5r","title":"OpenAI 推出 ChatGPT Wallet，让 AI Agent 代用户完成支付","summary":"OpenAI 推出 ChatGPT Wallet，让 AI Agent 代用户支付，此前因灵活性不足放弃了 Instant Checkout。该功能目前仅在美国通过 Dots 上线，需要 ChatGPT Pro 订阅和符合条件的美国银行卡；商家和 Agent 都看不到真实卡号，由 American Express、Mastercard 和 Visa 生成支付令牌完成付款。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T18:55:21.000Z","url":"https://the-decoder.com/openai-rebuilt-ai-shopping-from-scratch-with-chatgpt-wallet/"},{"id":"gtri2wqpaqm88wga1fo3unzkh","title":"OpenAI dots 智能体可通过 ChatGPT Wallet 购物，每笔需生物识别批准","summary":"OpenAI 的 dots 智能体现在可通过 ChatGPT Wallet 代用户购物，每次购买需生物识别批准。用户保存一次借记卡或信用卡后，智能体用以替代真实卡号的 token 支付，卡号对商户和智能体均不可见，持卡人保留原有奖励和保护；系统由 American Express、Mastercard 和 Visa 与 OpenAI 共同构建。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T18:01:47.000Z","url":"https://x.com/rohanpaul_ai/status/2121302521851621689"},{"id":"jj768amkn6ylnwh878i92r5ya","title":"OpenAI 联合 American Express、Mastercard 和 Visa 推出 ChatGPT Wallet","summary":"OpenAI 推出 ChatGPT Wallet，与 American Express、Mastercard 和 Visa 合作，让 dot 可安全代用户完成购物。智能体支付时无法接触真实卡片信息，每次购买都需安全检查和用户批准；功能即日起向美国 Pro 订阅用户的 dot 推出。","sourceName":"X：Greg Brockman (@gdb)","firstParty":false,"publishedAt":"2026-11-13T17:32:45.000Z","url":"https://x.com/gdb/status/2121295213025194172"},{"id":"czp2y4hzb8bf1qhwlqzvw7a7g","title":"OpenAI 推出 ChatGPT Wallet，智能体可在用户批准下代为支付","summary":"OpenAI 推出 ChatGPT Wallet，智能体（dot）可在用户批准下安全地代为完成购买，无需接触用户实际银行卡信息，每笔购买都需通过安全校验。该功能即日起向美国 Pro 订阅用户的 dot 推出。Codex 产品设计员工 Ed Bayes 转发宣布，并表示团队同时上线了多项体验改进，详情见 https://openai.com/index/introducing-chatgpt-wallet/。","sourceName":"X：Ed Bayes（OpenAI，Codex 产品设计） (@edbayes)","firstParty":false,"publishedAt":"2026-11-13T16:54:28.000Z","url":"https://x.com/edbayes/status/2121285578876719586"},{"id":"sx5a9s0pgv35iwywziinladgi","title":"ChatGPT 携手三大卡组织打造钱包","summary":"我们正与 American Express、Mastercard 和 Visa 携手，联合企业与开发者，共同打造 ChatGPT Wallet，让智能体支付值得信赖、稳定可靠。","sourceName":"X：ChatGPT (@ChatGPT)","firstParty":false,"publishedAt":"2026-11-13T16:44:49.000Z","url":"https://x.com/ChatGPT/status/2121283153205883030"},{"id":"vot1htumxjgnb0i88rbq3zsuq","title":"ChatGPT 推出 ChatGPT Wallet，dot 可在用户批准下代为完成购买","summary":"ChatGPT 官方账号宣布推出 ChatGPT Wallet，dot 可在用户批准下安全地代用户完成购买。智能体支付时不会接触用户的实际卡号信息，每笔购买都需要通过安全检查。该功能即日起在美国向 Pro 订阅用户的 dot 推出，详情见 https://openai.com/index/introducing-chatgpt-wallet/。","sourceName":"X：ChatGPT (@ChatGPT)","firstParty":false,"publishedAt":"2026-11-13T16:44:49.000Z","url":"https://x.com/ChatGPT/status/2121283151729496235"},{"id":"qb9i34aoob3o14uusgqvgwa22","title":"OpenAI 推出 ChatGPT Wallet，AI 智能体可代用户购物并完成结账","summary":"OpenAI 于周五推出 ChatGPT Wallet，用户可让名为 dot 的智能体帮助决策购物并代为完成结账。功能初期向限量美国 18 岁以上 ChatGPT Pro 订阅者开放，需绑定美国发行的 Visa、Mastercard 或 American Express。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T16:00:12.000Z","url":"https://techcrunch.com/2026/11/13/chatgpts-new-wallet-lets-ai-agents-shop-and-check-out-for-you/"},{"id":"g220zd8m7x2dqoi9qs3fokla8","title":"OpenAI 推出支付功能 ChatGPT Wallet，让 dot 智能体代用户购物","summary":"OpenAI 于 11 月 13 日推出支付功能 ChatGPT Wallet，与美国运通、万事达卡和 Visa 合作开发，让旗下 dot AI 智能体代替用户购物。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-13T15:49:08.710Z","url":"https://www.ithome.com/1/026/994.htm"},{"id":"up9jrgyt5vkvf24zv3wl8yg9l","title":"OpenAI 推出 ChatGPT Wallet，让智能体在用户批准下完成支付","summary":"OpenAI 推出 ChatGPT Wallet，为 ChatGPT Work、Codex 和 dots 中的智能体提供一种安全的支付方式。购买需经用户批准，并沿用用户现有银行卡的保护机制。","sourceName":"OpenAI：官网动态（RSS · 排除企业/客户案例）","firstParty":true,"publishedAt":"2026-11-13T15:00:00.000Z","url":"https://openai.com/index/introducing-chatgpt-wallet"}]},"77f8b937-8e1a-4b05-b3eb-b609445fedd4":{"publicId":"77f8b937-8e1a-4b05-b3eb-b609445fedd4","title":"DeepSeek 开放 App 能力 API，扩展调用另收费","status":"active","sourceCount":6,"reportCount":10,"firstReportAt":"2026-11-12T16:00:00.000Z","latestAt":"2026-11-13T20:31:51.000Z","latest":"DeepSeek 将聊天应用全栈能力开放给开发者 API","digest":"DeepSeek 于 11 月 13 日将 App 对话背后的能力开放给开发者：在原有 API 中开启对应参数，即可使用联网搜索、文件输入、阅读链接等功能，工具调用与上下文拼接由服务端完成。V4.1-Flash 模型（deepseek-flash）已在 Messages、Responses 与 Chat Completions 接口下支持这些能力；语音及底层能力另设独立接口，含 OCR、ASR、TTS，可单独或组合调用。\n\nDeepSeek 称，调用扩展能力时除 Token 费用外，还将收取相关工具的调用费用，具体定价随公告另行列出。对外提供应用服务的开发者须开启内容安全参数，并自行承担内容安全审核、大模型登记、AI 标识等义务。\n\n官方同时提供可导入 DeepSeek 对话历史的开源前端演示（github.com/deepseek-ai/chat-demo）。投资人 Tianyi Cui 转发公告称，开发者可用少量参数启用内置功能，在自建应用中还原完整 App 体验。","digestUpdatedAt":"2026-11-13T20:44:01.317Z","reports":[{"id":"gr7pw7syayjmnm461fnywxlon","title":"DeepSeek 将聊天应用全栈能力开放给开发者 API","summary":"DeepSeek 宣布将 DeepSeek App 背后的完整能力通过 API 开放，包括搜索、文件读取、链接打开、内容安全和语音。开发者可通过少量参数启用内置功能，或单独调用 OCR、ASR、TTS 等 API，并可试用开源前端 demo（支持导入 DeepSeek 对话历史），代码与文档已发布在 GitHub 和 api-docs.deepseek.com。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T20:31:51.000Z","url":"https://x.com/rohanpaul_ai/status/2121340286773457097"},{"id":"o2ud9vu2a6bmucuidc30u52zk","title":"下一个超级 App 不必是面向所有人的一个超级 App。 现在，每个人都有能力创造一个超级 App。 下一个超级 App 也可以是只属于你一个人的超级 App。","summary":"下一个超级 App 不必是面向所有人的一个超级 App。 现在，每个人都有能力创造一个超级 App。 下一个超级 App 也可以是只属于你一个人的超级 App。","sourceName":"X：Tianyi Cui（@tianyi）","firstParty":false,"publishedAt":"2026-11-13T15:31:21.000Z","url":"https://x.com/tianyi/status/2121264664571269160"},{"id":"jak4hoym9ycotkw4heqsfryp9","title":"DeepSeek 开放全家桶应用 API，开发者可 1:1 复刻 DeepSeek App","summary":"DeepSeek 于 11 月 13 日晚宣布正式开放全家桶应用 API，在原有 API 中开启对应参数即可获得深度思考搜索、文件输入等对话功能，语音及底层能力也开放独立接口。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-13T14:29:06.313Z","url":"https://www.ithome.com/1/026/960.htm"},{"id":"aqnmn2n2rzh2yjbniearntagd","title":"DeepSeek 将 App 核心能力通过 API 开放并附开源前端演示","summary":"作者转发 DeepSeek 官方公告：DeepSeek App 背后的搜索、文件、链接、安全和语音等能力现已通过 DeepSeek API 开放，可通过少量参数启用内置功能，或调用 OCR、ASR、TTS 等独立 API，在自建应用中还原完整 App 体验。官方同时提供支持导入 DeepSeek 对话历史的开源前端演示，代码见 https://github.com/deepseek-ai/chat-demo，详情见 https://api-docs.deepseek.com/guides/build_a_chatbot。作者期待功能实现门槛降低后社区能产出更多样的产品。","sourceName":"X：Tianyi Cui（@tianyi）","firstParty":false,"publishedAt":"2026-11-13T14:28:07.000Z","url":"https://x.com/tianyi/status/2121248749343420437"},{"id":"ywxxfyptevy24rytjj3n4q2td","title":"DeepSeek App 能力开放自由调用","summary":"🌱 更多可能性，等你来构建\n\nDeepSeek App 只是与 AI 交互的一种方式。它的能力现在可以由你自由调用与组合。少花时间重建基础功能，多花时间创造新事物。\n\n用 DeepSeek 构建。让想象力引领。\n\n4/4","sourceName":"X：DeepSeek (@deepseek_ai)","firstParty":false,"publishedAt":"2026-11-13T14:24:46.000Z","url":"https://x.com/deepseek_ai/status/2121247907076813077"},{"id":"t24t8354ribo501q0x9aymjo1","title":"DeepSeek API 工具调用计费说明","summary":"💰 API 定价\n\n扩展能力除标准 token 费用外，还会产生工具使用费用。\n工具定价明细见下文。\n\n3/4","sourceName":"X：DeepSeek (@deepseek_ai)","firstParty":false,"publishedAt":"2026-11-13T14:24:45.000Z","url":"https://x.com/deepseek_ai/status/2121247903603941471"},{"id":"c519wztfethigml59ijbepa9x","title":"DeepSeek 将 App 全套能力开放至 API，含搜索、文件与语音","summary":"DeepSeek 宣布 App 背后的能力现已通过 DeepSeek API 开放，涵盖搜索、文件、链接、安全与语音。开发者可用少量参数启用内置功能，或单独调用 OCR、ASR、TTS 等 API，并提供了支持导入 DeepSeek 对话历史的开源前端 Demo。","sourceName":"X：DeepSeek (@deepseek_ai)","firstParty":false,"publishedAt":"2026-11-13T14:24:44.000Z","url":"https://x.com/deepseek_ai/status/2121247896918253875"},{"id":"pccvkmzla239p7ysemtetxx4p","title":"DeepSeek V4.1-Flash 支持内置搜索、文件解析与安全检查等工具能力","summary":"DeepSeek 宣布 V4.1-Flash（deepseek-flash）在 Messages、Responses 和 Chat Completions 中支持内置工具，工具调用和上下文组装由服务端处理。","sourceName":"X：DeepSeek (@deepseek_ai)","firstParty":false,"publishedAt":"2026-11-13T14:24:44.000Z","url":"https://x.com/deepseek_ai/status/2121247899699036516"},{"id":"w1edyi7hrsgj7uk5j4amwwwff","title":"DeepSeek 开放全家桶应用 API，V4.1-Flash 支持联网搜索、文件输入与语音独立接口","summary":"DeepSeek 官方宣布开放全家桶应用 API，在原有 API 中开启对应参数即可获得深度思考搜索、文件输入、阅读链接、模型安全等对话能力，V4.1-Flash 模型（deepseek-flash）已在 Messages、Responses 与 Chat Completions 接口下支持这些功能。","sourceName":"公众号：DeepSeek（深度求索）","firstParty":false,"publishedAt":"2026-11-13T14:19:36.000Z","url":"https://mp.weixin.qq.com/s/78KBHc4-4N5b2vfL9SkutQ"},{"id":"nnbnoebf6mvo97usmwj5wziyl","title":"DeepSeek 开放全家桶应用 API：联网搜索、文件输入、阅读链接等能力面向开发者","summary":"DeepSeek 在 API 中开放此前 App 对话服务所用的能力，开发者开启对应参数即可使用，工具调用与上下文拼接由服务端完成。","sourceName":"DeepSeek：API 更新日志","firstParty":true,"publishedAt":"2026-11-12T16:00:00.000Z","url":"https://api-docs.deepseek.com/zh-cn/updates/#发布全家桶应用-api"}]},"44c4eb23-1f37-4994-a66d-7a06ff7a74ba":{"publicId":"44c4eb23-1f37-4994-a66d-7a06ff7a74ba","title":"llama.cpp 与 ggml 发布首个大版本 v1.0.0","status":"active","sourceCount":6,"reportCount":8,"firstReportAt":"2026-11-04T16:34:40.000Z","latestAt":"2026-11-14T00:14:06.727Z","latest":"llama.cpp 与 ggml 迈入 1.0.0，支持超 150 种模型架构","digest":"llama.cpp 作者 Georgi Gerganov 于 11 月 13 日宣布 llama.cpp 与底层引擎 ggml 的库版本进入 v1.0.0，称这是两者的首个大版本。此前 11 月 5 日发布 v0.9.0 时，他曾表示将在“接下来几周”迈向 v1.0.0。\n\n据 Hugging Face 博客，团队承诺今后以主版本号标识 API 和 ABI 不兼容变更，并公开语义化版本更新规则。Hugging Face CEO Clément Delangue 与 Gerganov 一同宣布，称这是运行本地 AI 模型最常用库的首个完全稳定大版本；他称用户可在手机、笔记本和工作站上免费掌控自己的智能、不向任何人发送数据，并承诺支持所有硬件、平台和模型类型。这些是发布方的说法。\n\n据 IT之家报道，该版本支持超过 150 种模型架构。Cohere 转发发布消息，并称已将 llama.cpp 支持加入 North Micro Vision。","digestUpdatedAt":"2026-11-14T00:22:06.294Z","reports":[{"id":"gtx717vmc7dsnzr96jmugn5g4","title":"Latent Space 发布《No AI Slop 宣言》，llama.cpp 与 SGLang 同期迈入 1.0","summary":"Latent Space 发布《No AI Slop 宣言》，该宣言源自 AIE CODE 会议讨论，由 Dex 在闭幕演讲中提出，并获多位演讲者联署。同期 llama.cpp 与 ggml 宣布达到 1.0，从公开头文件中移除 35 个废弃函数；SGLang 也在近期 SGLang Summit 上宣布 1.0。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-14T08:31:02.000Z","url":"https://latent.space/p/ainews-the-no-ai-slop-manifesto/"},{"id":"ave67u5kkw0kseoszlmul2vdx","title":"llama.cpp 与 ggml 迈入 1.0.0，支持超 150 种模型架构","summary":"开发者 Georgi Gerganov 于 11 月 13 日宣布 llama.cpp 与底层引擎 ggml 库版本迈入 1.0.0。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-14T00:14:06.727Z","url":"https://www.ithome.com/1/027/019.htm"},{"id":"hfr3pappi4gx1p2iut90pwffl","title":"Cohere 宣布 North Micro Vision 支持 llama.cpp，并转发 llama.cpp v1.0.0 发布","summary":"Cohere 转发 llama.cpp v1.0.0 发布消息，称这是最常用本地运行 AI 模型库的首个完全稳定主版本，可在手机、笔记本和工作站本地运行模型。Cohere 同时宣布近期已将 llama.cpp 支持加入 North Micro Vision，使其最新架构全部获得支持，并表示后续将提供更多开发者支持。","sourceName":"X：Cohere（@cohere）","firstParty":false,"publishedAt":"2026-11-13T19:59:06.000Z","url":"https://x.com/cohere/status/2121332046417031258"},{"id":"um8pmpa91qn1ymvx3pux0sq1x","title":"llama.cpp v1.0.0 发布，本地运行 AI 模型迎来首个稳定大版本","summary":"Hugging Face CEO Clément Delangue 与 @ggerganov 宣布 llama.cpp v1.0.0 发布，这是这个最常用的本地运行 AI 模型库的首个完全稳定大版本。作者称用户可在手机、笔记本和工作站上免费掌控自己的智能，不向任何人发送数据，并承诺支持所有硬件、平台和模型类型，让 AI 分布式而非集中于少数硅谷机构。","sourceName":"X：Clément Delangue（Hugging Face CEO） (@ClementDelangue)","firstParty":false,"publishedAt":"2026-11-13T15:13:14.000Z","url":"https://x.com/ClementDelangue/status/2121260104913768931"},{"id":"a53910czfauzrquoz6ps7ljdp","title":"llama.cpp 与 ggml 发布首个大版本","summary":"Georgi Gerganov 宣布今日发布是 llama.cpp 和 ggml 的首个大版本，表示已为本地 AI 的未来打下坚实基础，并期待社区在此基础上构建更多应用。","sourceName":"X：Georgi Gerganov（llama.cpp） (@ggerganov)","firstParty":false,"publishedAt":"2026-11-13T14:21:24.000Z","url":"https://x.com/ggerganov/status/2121247058451411047"},{"id":"qfkqwt8cam03c34j4fxxuowgq","title":"llama.cpp v1.0.0 正式发布","summary":"Georgi Gerganov 宣布 llama.cpp v1.0.0 现已可用，并附上 Hugging Face 官方博客 https://huggingface.co/blog/ggml-org/llama-cpp-v1 供了解详情。","sourceName":"X：Georgi Gerganov（llama.cpp） (@ggerganov)","firstParty":false,"publishedAt":"2026-11-13T14:17:36.000Z","url":"https://x.com/ggerganov/status/2121246103312212124"},{"id":"mqttq6z0b05y9sd6v1c4kc8kx","title":"llama.cpp 与 ggml 发布 v1.0.0 稳定库","summary":"Hugging Face 的 llama.cpp 团队发布 llama.cpp 和 ggml 的 v1.0.0 库，承诺今后以主版本号标识 API 和 ABI 不兼容变更，并公开语义化版本更新规则。","sourceName":"Hugging Face 社区博客（混合发现）","firstParty":false,"publishedAt":"2026-11-13T14:05:22.000Z","url":"https://huggingface.co/blog/ggml-org/llama-cpp-v1"},{"id":"x55e06faazg28ifz13kyuzeai","title":"llama.cpp v0.9.0 发布，迈向 v1.0.0","summary":"今天我们发布 llama.cpp v0.9.0，接下来几周我们将朝着首个重要版本 v1.0.0 迈进\n\nhttps://github.com/ggml-org/llama.cpp/releases/tag/v0.9.0","sourceName":"X：Georgi Gerganov（llama.cpp） (@ggerganov)","firstParty":false,"publishedAt":"2026-11-04T16:34:40.000Z","url":"https://x.com/ggerganov/status/2118019105869492301"}]},"4d02a2b5-ec70-4631-a88c-702e78e77fc0":{"publicId":"4d02a2b5-ec70-4631-a88c-702e78e77fc0","title":"OpenAI解散机器人团队，研究人员并入其他部门","status":"active","sourceCount":1,"reportCount":1,"firstReportAt":"2026-11-14T11:40:51.000Z","latestAt":"2026-11-14T11:40:51.000Z","latest":"OpenAI 将机器人研究员并入其他团队，押注通用模型替代专用机器人 AI","digest":"据 Fortune 报道，OpenAI 正在解散机器人团队，将机器人研究员转入 Mark Chen 领导的主研究团队，应用机器人与硬件团队则加入 Greg Brockman 的 Applied 组织。\n\nThe Decoder 称，OpenAI 此次并非放弃机器人方向，而是希望把研究人员并入其他团队，以通用模型替代专用机器人 AI，从而加快进展。这一说法来自报道方，OpenAI 尚未公布重组后的具体计划或效果。","digestUpdatedAt":"2026-11-14T12:26:10.625Z","reports":[{"id":"zvo2ciiibpmh00lmqkggnsl5r","title":"OpenAI 将机器人研究员并入其他团队，押注通用模型替代专用机器人 AI","summary":"据 Fortune 报道，OpenAI 正在解散机器人团队并将研究员并入其他部门：机器人研究员转入 Mark Chen 领导的主研究团队，应用机器人与硬件团队加入 Greg Brockman 的 Applied 组织。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-14T11:40:51.000Z","url":"https://the-decoder.com/openai-reassigns-robotics-researchers-to-other-teams-as-general-purpose-models-might-make-specialized-robotics-ai-unnecessary/"}]},"68ccf963-6e38-4e86-b2f3-289bd70774fb":{"publicId":"68ccf963-6e38-4e86-b2f3-289bd70774fb","title":"NVIDIA员工联署要求董事会辞职，董事会另寻继任者","status":"active","sourceCount":8,"reportCount":8,"firstReportAt":"2026-11-13T08:23:04.000Z","latestAt":"2026-11-13T20:07:34.000Z","latest":"WSJ 报道称黄仁勋被罢免更多源于 Nvidia 高风险业务而非私生活","digest":"据 X.PIN 转发的一封内部公开信，数百名 NVIDIA 员工签署该信，要求董事会辞职并恢复黄仁勋的 CEO 职务。信中指控董事会在没有具体证据的情况下罢免黄仁勋，并称董事会未诚信谈判；若董事会不满足要求，这些员工可能转投 Elon Musk 承诺安排职位的 SpaceX 与 Terafab。上述指控与离职去向均为信中说法。\n\n据 FT 报道，NVIDIA 董事会已接触 Arm CEO Rene Haas，将其作为接替黄仁勋的可能人选。Haas 自 2022 年起执掌这家软银旗下的英国芯片设计公司，十多年前曾在 NVIDIA 工作约 7 年，但他只是多位候选人之一，未必会获得或接受这一职位。\n\nThe Decoder 援引 WSJ 报道称，黄仁勋被罢免更多源于其主导的高风险业务，而非私生活传闻：NVIDIA 向 AI 云厂商和数据中心开发商提供数十亿美元财务担保以换取营收分成，最大一笔涉及对 OpenAI 俄亥俄数据中心的 2500 亿美元担保，消息公布后股价跌 5%，临时 CEO Colette Kress 将该承诺减半。","digestUpdatedAt":"2026-11-13T20:12:11.158Z","reports":[{"id":"s59xfwl0atld8vs7xq0pdx6hw","title":"WSJ 报道称黄仁勋被罢免更多源于 Nvidia 高风险业务而非私生活","summary":"The Decoder 援引 WSJ 报道分析称，黄仁勋被罢免更多源于 Nvidia 高风险业务而非私生活传闻。Nvidia 在其主导下向 AI 云厂商和数据中心开发商提供数十亿美元财务担保以换取营收分成，最大一笔涉及对 OpenAI 俄亥俄数据中心的 2500 亿美元担保，消息公布后股价跌 5%，临时 CEO Colette Kress 将该承诺减半。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-13T20:07:34.000Z","url":"https://the-decoder.com/jensen-huangs-ouster-likely-traces-back-to-nvidias-risky-business-practices-more-than-his-personal-life/"},{"id":"p1mfh9oe0xbq4evyru5pp1ikt","title":"Nvidia 危机与 Anthropic IPO 前夜的 Cerebral Valley AI Summit 现场观察","summary":"Newcomer 在旧金山 Cerebral Valley AI Summit 现场报道：Jensen Huang 因第二段婚外情披露辞职，Reuters 当天报道存在第三段，与会者多认为 Nvidia 短期无碍但生态承压，Databricks CEO 称其对整个生态是打击。","sourceName":"Newcomer 新闻长文（RSS）","firstParty":false,"publishedAt":"2026-11-13T19:27:39.000Z","url":"https://www.newcomer.co/p/nvidia-crises-anthropic-ipo-and-off"},{"id":"wk33v2eb2ubx9wca68hhwm901","title":"FT 报道 Nvidia 董事会接触 Arm CEO Rene Haas 考虑接替黄仁勋","summary":"据 FT 报道，Nvidia 董事会接触了 Arm CEO Rene Haas，作为接替黄仁勋的可能人选。Haas 自 2022 年起执掌这家软银旗下的英国芯片设计公司，十多年前曾在 Nvidia 工作约 7 年，与黄仁勋及部分董事保持密切关系，但他只是多位候选人之一，未必会获得或接受这一职位。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-13T17:34:44.000Z","url":"https://x.com/rohanpaul_ai/status/2121295713502199821"},{"id":"wkxqhc700pv5zgpew0cj5zyec","title":"Vergecast 播客解读黄仁勋辞任 NVIDIA CEO 后的连锁影响","summary":"The Vergecast 播客中 David Pierce 与 Nilay 梳理 NVIDIA CEO 黄仁勋周四辞职事件，并讨论后续可能展开的更大故事：NVIDIA 在中国的业务、美国政府的态度，以及整个 AI 行业的稳定性。","sourceName":"The Verge：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T14:47:16.000Z","url":"https://www.theverge.com/podcast/1032866/jensen-huang-nvidia-china-trump-vergecast"},{"id":"pdhda5tufq7ubi8w17bys7w66","title":"Nvidia 领导层变动引发以色列科技界关注，投资人认为挑战者或有机会","summary":"Nvidia 前CEO黄仁勋辞职后，以色列科技界关注这家在其拥有6000名员工和最大海外研发中心的公司是否会继续深耕以色列。多位以色列投资人认为，Nvidia 决策放缓可能给 AI 芯片和推理软件领域的竞争者留出空间，但如果不确定性也拖慢 AI 支出，竞争者面对的可能是更小的市场机会。","sourceName":"TechCrunch：AI（RSS）","firstParty":false,"publishedAt":"2026-11-13T12:52:19.000Z","url":"https://techcrunch.com/2026/11/13/israels-vcs-see-opportunity-for-challengers-in-nvidias-turmoil/"},{"id":"se0y4v3gihr6s0jmrc5vuv1zo","title":"AINews：黄仁勋辞任 NVIDIA CEO，Colette Kress 出任临时 CEO","summary":"Latent Space 的 AI 新闻日报头条是 NVIDIA 宣布黄仁勋在任职 33 年后辞去 CEO、总裁和董事职务，CFO Colette Kress 出任临时 CEO，SEC 文件显示董事会于 11 月 11 日接受辞呈，此前董事会已就 NYT 报道的绯闻事件展开独立调查。","sourceName":"Latent Space（RSS）","firstParty":false,"publishedAt":"2026-11-13T09:04:13.000Z","url":"https://latent.space/p/ainews-jensen-huang-resigns-after-33-years-leading-nvidia/"},{"id":"w9235nqq0senjfvm8lz7g51aa","title":"NVIDIA 员工内部信要求董事会辞职并恢复黄仁勋 CEO 职务","summary":"X.PIN 转发消息称，数百名 NVIDIA 员工签署内部公开信，要求董事会辞职并恢复黄仁勋 CEO 职务。信中指控董事会在无具体证据的情况下罢免黄仁勋、诚信谈判，称若董事会不满足要求，员工可能转投 Elon Musk 承诺安排职位的 SpaceX 与 Terafab，并列出 Bill Daly、Ian Buck 等署名员工。","sourceName":"X：X.PIN (@thexpin)","firstParty":false,"publishedAt":"2026-11-13T08:23:04.000Z","url":"https://x.com/thexpin/status/2121156882064937448"},{"id":"n73ab4h9gqlu6ucv69ynzxln4","title":"SemiAnalysis 分析黄仁勋辞任 Nvidia 后的公司结构与出口管制走向","summary":"SemiAnalysis 长文分析黄仁勋辞任 Nvidia CEO 后的连锁影响，作者推测其去职与 GPU 走私及美国推动 RASA 出口管制立法有关。文中指出公司约 60 名直管高管的扁平结构依赖黄本人，继任者 Colette Kress 为临时 CEO，Ian Buck 与 Jonah Alben 被视为技术侧人选但无人能全面接替。","sourceName":"SemiAnalysis 长文 RSS（RSS）","firstParty":false,"publishedAt":"2026-11-12T18:06:26.000Z","url":"https://newsletter.semianalysis.com/p/nvidia-and-the-world-without-jensen"}]},"dad94af2-7539-4652-a661-03cc5494c71b":{"publicId":"dad94af2-7539-4652-a661-03cc5494c71b","title":"Anthropic 向 Team 和 Enterprise 推出 Claude Meetings beta","status":"active","sourceCount":8,"reportCount":11,"firstReportAt":"2026-11-12T00:00:00.000Z","latestAt":"2026-11-12T22:36:29.000Z","latest":"Anthropic 发布 Claude Meetings，Claude 可加入团队视频会议协作","digest":"Anthropic 以 beta 形式向 Team 和 Enterprise 计划推出 Claude Meetings，可在 Claude 和 Claude Desktop 中使用。Claude 作为可见参与者加入 Google Meet 通话，团队成员可口头或在聊天中提问、让它起草文档，并实时看到和纠正它生成的内容；通话结束后，笔记、行动项、转录和 Claude 生成的内容都保存在 Claude 中该会议的页面上。\n\nAnthropic 称目前从 Google Meet 开始支持，其他视频会议平台的支持即将推出，但未公布时间。据 Rohan Paul 介绍，Claude 会对每个口头请求先确认发言者身份再执行；默认情况下，一旦有组织外部人员加入 Google Meet 通话，它就会退出。The Decoder 报道称，采用 HIPAA 或客户管理加密配置的组织暂时无法使用 Meetings。\n\n费用方面，Anthropic 称 beta 期间 Team 和 Enterprise 计划的笔记和转录免费，通话中的回答也免费，但回答若调用已连接的工具，则计入该计划用量；通话中生成的文档、白板等产物免费至 2027 年 2 月 10 日。该功能目前仅限上述两个计划，且处于 beta 阶段，尚未公布面向其他计划或正式版的时间。","digestUpdatedAt":"2026-11-12T22:49:22.048Z","reports":[{"id":"kikcmqsbwnwg3mb8xoh2h2dot","title":"Anthropic 发布 Claude Meetings，Claude 可加入团队视频会议协作","summary":"Anthropic 推出 Claude Meetings，可将 Claude 加入团队视频通话，在会议进行中与你共同生成文档、白板等 artifacts。该功能已在 Team 和 Enterprise 计划以 beta 形式开始逐步推送。","sourceName":"X：Ado Kukic（Anthropic 开发者关系，Claude Code） (@adocomplete)","firstParty":false,"publishedAt":"2026-11-12T22:36:29.000Z","url":"https://x.com/adocomplete/status/2121009263997010306"},{"id":"fyy46ximozmo3jopdn6viv7w4","title":"Anthropic 推出 Claude Meetings，可加入团队视频通话实时协作","summary":"Anthropic 推出 Claude Meetings：把 Claude 加入团队视频通话后，它能在你还在讲话时就与你一起构建文档、白板等产物。该功能正以 beta 形式开始向 Team 和 Enterprise 计划推出。","sourceName":"X：Noah Zweben（@noahzweben）","firstParty":false,"publishedAt":"2026-11-12T21:15:49.000Z","url":"https://x.com/noahzweben/status/2120988963137810578"},{"id":"fii8iaht4yklmdxiud8qy18od","title":"Anthropic 推出 Claude Meetings，让 Claude 以参会者身份加入视频会议","summary":"Anthropic 推出 Claude Meetings 功能，让 Claude 以可见参会者身份加入视频通话，可回答问题、生成文档和白板、记录笔记与行动项。会议结束后所有产出可在 claude.ai 专用页面查看。","sourceName":"The Decoder：AI News（RSS）","firstParty":false,"publishedAt":"2026-11-12T20:26:50.000Z","url":"https://the-decoder.com/claude-meetings-lets-anthropics-ai-join-your-video-calls/"},{"id":"eifuwvcjk4e3hk7iedz0ur7zj","title":"Anthropic 推出 Claude Meetings，可像参会者一样加入 Google Meet","summary":"Rohan Paul 介绍 Anthropic 新推出的 Claude Meetings（beta），可像参会者一样加入 Google Meet，在会中实时听取并完成通常会后才安排的工作。","sourceName":"X：Rohan Paul (@rohanpaul_ai)","firstParty":false,"publishedAt":"2026-11-12T20:20:44.000Z","url":"https://x.com/rohanpaul_ai/status/2120975099960721597"},{"id":"ejdq68qv8qvj61bp0suii0270","title":"Claude Meetings 现支持 Google Meet，更多视频会议平台即将加入","summary":"Anthropic 官方宣布 Claude Meetings 从 Google Meet 开始支持，其他视频会议平台的支持即将推出。详情见 https://claude.com/resources/articles/claude-meetings。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-12T20:16:22.000Z","url":"https://x.com/claudeai/status/2120974000746582357"},{"id":"khunutyhfztjlbm52uzwlze4q","title":"Claude 加入会议成为可见参与者","summary":"Claude 作为可见参与者加入。你可以大声提问或在聊天中提问，也可以让它起草文档。你的团队能看到它正在构建的内容，并在成形过程中进行纠正。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-12T20:16:21.000Z","url":"https://x.com/claudeai/status/2120973996304830859"},{"id":"kq2om5zvywnzs9u87374sf9q6","title":"Claude 新增会议记录功能，会后自动整理笔记与行动项","summary":"Anthropic 的 Claude 宣布接管会议记录工作。通话结束后，笔记、行动项、转录内容以及 Claude 生成的一切产出都会保存在 Claude 中该会议的页面上。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-12T20:16:21.000Z","url":"https://x.com/claudeai/status/2120973999295643679"},{"id":"iifokh8bszrjeauww4d3ri073","title":"Anthropic 发布 Claude Meetings，可在视频会议中与团队协作生成文档和白板","summary":"Anthropic 推出 Claude Meetings，把 Claude 加入团队视频通话后，它能在对话进行中与你共同构建文档、白板等 artifacts。该功能正以 beta 形式在 Team 和 Enterprise 计划上逐步推出。","sourceName":"X：Claude (@claudeai)","firstParty":false,"publishedAt":"2026-11-12T20:16:20.000Z","url":"https://x.com/claudeai/status/2120973994191094179"},{"id":"flobw48sm2tlkfp190q774nqq","title":"Anthropic 推出 Claude Meetings，可在视频会议中实时协作并生成会议产物","summary":"Anthropic 推出 Claude Meetings，把 Claude 以可见参会者身份加入团队视频会议，在通话过程中实时创建文档、白板等产物，团队成员可边看边纠正，Claude 同时负责会议记录。","sourceName":"Claude：YouTube（RSS）","firstParty":true,"publishedAt":"2026-11-12T20:10:59.000Z","url":"https://www.youtube.com/watch?v=YUYeHMsqbmY"},{"id":"hyhofad7x4ang7yxog447pw08","title":"Claude Meetings 在 Team 和 Enterprise 计划开启 beta 测试","summary":"Claude Meetings 在 Claude 和 Claude Desktop 上向 Team 和 Enterprise 计划以 beta 形式推出。用户可将 Claude 作为可见参与者加入 Google Meet 通话，在通话中记笔记、回答问题，并构建 docs、白板和幻灯片等 artifacts。","sourceName":"Claude 应用发布说明","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://support.claude.com/en/articles/12138966-release-notes#h_2d03630102"},{"id":"l36ne5q2gsdx6thyia7fi10kn","title":"Anthropic 推出 Claude Meetings，Claude 以参会者身份加入视频会议","summary":"Anthropic 推出 Claude Meetings beta，Claude 可作为可见参会者加入视频通话，在会中回答提问、协作创建文档和白板，并生成笔记和行动项。","sourceName":"Claude：Blog（网页）","firstParty":true,"publishedAt":"2026-11-12T00:00:00.000Z","url":"https://claude.com/blog/claude-meetings"}]},"f39357ff-614c-4933-bc75-31ede55ae3b2":{"publicId":"f39357ff-614c-4933-bc75-31ede55ae3b2","title":"Gemini 接入 Google Wallet，仅可读取账户","status":"active","sourceCount":2,"reportCount":3,"firstReportAt":"2026-11-13T17:27:13.000Z","latestAt":"2026-11-14T06:57:17.463Z","latest":"谷歌 Gemini 个人智能功能接入 Google Wallet，可分析消费习惯并给个性化建议","digest":"Google 将 Google Wallet 加入 Gemini 个人智能的可连接应用。用户完成授权后，可在对话中输入 @Google Wallet，让 Gemini 根据消费习惯回答个人财务问题，例如生成现金流、资产配置和预算图表，找出遗忘的订阅与周期性扣费，并标记涨价；还可通过 Plaid 关联信用卡和银行账户，以获得更全面的分析。\n\nGoogle 称，连接 Wallet 后 Gemini 只能读取用户授权的账户信息，无法转账、管理资金或投资。该接入为自愿授权，用户需在个人智能设置的“已连接的应用”中手动开启，并可随时取消。","digestUpdatedAt":"2026-11-14T07:38:21.542Z","reports":[{"id":"i0ovzg52212cfih11tqxr3grl","title":"谷歌 Gemini 个人智能功能接入 Google Wallet，可分析消费习惯并给个性化建议","summary":"谷歌宣布 Gemini 的 Personal Intelligence（个人智能）功能正式支持 Google Wallet，用户在对话中输入 @Google Wallet 即可询问财务状况、消费情况和预算规划。通过 Plaid 关联信用卡和银行账户后，Gemini 可生成消费图表并协助制定储蓄计划；该功能仅读取授权账户信息，无法转账或投资，接入为自愿授权，可随时取消。","sourceName":"IT之家·人工智能","firstParty":false,"publishedAt":"2026-11-14T06:57:17.463Z","url":"https://www.ithome.com/1/027/141.htm"},{"id":"vtbzlrc5srvma7dycld0ovk9f","title":"Gemini 钱包连接仅可读取账户","summary":"@GeminiApp 我们在构建这些工具时以安全和隐私为核心。如果你选择连接钱包，Gemini 只能读取你的账户；它无法转移、管理或投资你的资金。了解更多。https://goo.gle/3UBasU9","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T17:27:14.000Z","url":"https://x.com/Google/status/2121293826908197347"},{"id":"cpkcs6wcdx3lvoxsiqs3edi4o","title":"Gemini 个人智能接入 Google Wallet","summary":"Gemini 的个人智能功能新增 Google Wallet 为可连接应用，可基于用户消费习惯回答个人财务问题。用户能在对话中生成现金流、资产配置和预算的动态图表，找出遗忘的订阅与周期性扣费，并让 Gemini 标记涨价。还可通过 Plaid 安全关联信用卡和银行账户，设置节日预算等个性化建议。","sourceName":"X：Google (@Google)","firstParty":false,"publishedAt":"2026-11-13T17:27:13.000Z","url":"https://x.com/Google/status/2121293823837921433"}]}}};
